window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q14"]=window.__LIBQ["the-gioi-hoan-my"]["q14"]||{};window.__LIBQ["the-gioi-hoan-my"]["q14"]["techniques"]={"updatedAt":"2026-07-26","count":90,"techniques":[{"id":"cuu-chuyen-quyen-an","name":"Cửu chuyển quyền ấn","cn":"","loai":"than-thong","loaiLabel":"Quyền pháp","phamCap":"","hePhai":"","soHuu":["Mạnh Thiên Chính"],"blurb":"Quyền pháp được Mạnh Thiên Chính dùng để hợp nhất nhiều tầng quyền quang và đối đầu Nguyên Thần kiếm thai.","detail":"Mạnh Thiên Chính chồng chất quyền ấn như nhiều tầng sóng, thực hiện cửu chuyển bằng hai tay rồi tập trung toàn bộ quyền quang. Đòn đánh va chạm trực diện với Nguyên Thần kiếm thai trong nơi sâu của vũ trụ.","congNang":["Hợp nhất quyền quang nhiều tầng thành một đòn công kích tập trung."],"uyLuc":"Có thể đối đầu trực diện với Nguyên Thần kiếm thai do Bình Loạn Quyết hiển hóa.","nguoiTu":[{"ten":"Mạnh Thiên Chính","tuChuong":"@c1301","tangDatToi":"","trangThai":"thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c1301","loai":"thi triển","importance":"normal","giaiDoan":"Cửu chuyển hợp nhất quyền quang","text":"Mạnh Thiên Chính thi triển cửu chuyển quyền ấn để đối đầu Nguyên Thần kiếm thai của Vương Trường Sinh.","anchor":"Đại Trường Lão hai tay giương ra, tiến hành rồi cửu chuyển"}]},"capNhatToi":"@c1301","nguon":["@c1301"]},{"id":"vo-thuong-tran-phap-vuong-gia","name":"Vô thượng trận pháp Vương gia","cn":"","loai":"khac","loaiLabel":"Trận pháp phòng hộ","phamCap":"","hePhai":"Vương gia","soHuu":["Vương gia"],"blurb":"Trận pháp bảo vệ cổ địa Vương gia, lấy những núi lớn khắc Tiên Đạo phù văn làm bộ phận cấu thành.","detail":"Một ngọn núi thuộc trận pháp đã giải thể và nổ tung dưới sức ép từ cuộc quyết đấu. Vương Cửu sau đó tự mình chủ trì, khiến các núi còn lại cùng cộng hưởng để bảo vệ cổ địa.","congNang":["Liên kết các núi lớn khắc Tiên Đạo phù văn để phòng ngự cổ địa Vương gia."],"dacDiem":"Các núi lớn khắc Tiên Đạo phù văn là những bộ phận của toàn trận.","nguoiTu":[{"ten":"Vương Cửu","tuChuong":"@c1301","tangDatToi":"","trangThai":"chủ trì"}],"tabs":{"tienTrinh":[{"chuong":"@c1301","loai":"xuất hiện","importance":"normal","giaiDoan":"Hư hại trong quyết đấu","text":"Một ngọn núi cấu thành trận pháp bị phá hủy, sau đó Vương Cửu chủ trì toàn trận để bảo vệ cổ địa.","anchor":"đây là bộ tộc ta Tiên Đạo di sản, là vô thượng trận pháp một phần"}]},"capNhatToi":"@c1301","nguon":["@c1301"]},{"id":"te-dan-mo-thien-lo","name":"Tế đàn mở Thiên lộ","cn":"","loai":"khac","loaiLabel":"Trận pháp truyền tống","phamCap":"Không rõ","hePhai":"Thiên Thần Thư Viện","soHuu":["Thiên Thần Thư Viện"],"blurb":"Trận pháp tế đàn quy mô lớn dùng để mở Thiên lộ xuyên qua giới bích.","detail":"Tế đàn nằm sâu trong Thiên Thần Thư Viện, có thể tạo thông đạo vũ trụ đủ lớn và ổn định để hàng ngàn vạn chiến thuyền vượt qua các vùng trời.","thuocTinh":"Không gian và truyền tống","congNang":["Mở thông đạo xuyên qua giới bích để vận chuyển cả hạm đội đến Đại Xích Thiên."],"nguoiTu":[],"tabs":{"tienTrinh":[{"chuong":"@c1306","loai":"thi triển","importance":"normal","giaiDoan":"Mở đường xuất chinh","text":"Tế đàn của Thiên Thần Thư Viện mở Thiên lộ để toàn bộ hạm đội vượt giới bích tiến vào Đại Xích Thiên.","anchor":"Thiên Thần Thư Viện có như vậy tế đàn, có thể mở ra \"Thiên lộ\""}]},"capNhatToi":"@c1306","nguon":["@c1306"]},{"id":"sat-phat-dai-tran-tren-co-thuyen","name":"Sát phạt đại trận trên cổ thuyền","cn":"","loai":"khac","loaiLabel":"Trận pháp chiến đấu","phamCap":"Không rõ","hePhai":"Cửu thiên thập địa","soHuu":[],"blurb":"Đại trận chiến đấu được bố trí trên các cổ thuyền của hạm đội cửu thiên thập địa.","detail":"Khi đoàn quân áp sát chiến trường Đại Xích Thiên, các cổ thuyền đồng loạt mở sát phạt đại trận và phối hợp với phù văn chí cao của các tộc để chuẩn bị công kích.","thuocTinh":"Sát phạt","congNang":["Đưa các cổ thuyền vào trạng thái sẵn sàng công kích khi đại chiến bùng nổ."],"nguoiTu":[],"tabs":{"tienTrinh":[{"chuong":"@c1306","loai":"thi triển","importance":"normal","giaiDoan":"Chuẩn bị giao chiến","text":"Các cổ thuyền đồng loạt mở sát phạt đại trận khi tiến gần phế tích hùng quan Đại Xích Thiên.","anchor":"sở hữu cổ thuyền mở ra sát phạt đại trận"}]},"capNhatToi":"@c1306","nguon":["@c1306"]},{"id":"van-toc-phu-van-cong-minh","name":"Vạn tộc phù văn cộng minh","cn":"","loai":"than-thong","loaiLabel":"Phù văn hợp kích","phamCap":"Không rõ","hePhai":"Vạn tộc","soHuu":[],"blurb":"Phương thức hợp kích dung hội phù văn và áo nghĩa của hơn vạn chủng tộc thành một lực lượng cộng minh.","detail":"Phù văn của các tộc được phát động từ nhiều cổ thuyền, hội tụ thành vô thượng kinh văn và gây ra dị tượng hư không nổ tung, Hỗn Độn cuồn cuộn cùng hư ảnh Luân Hồi. Thế công vẫn bị bàn tay của sinh linh Bất Hủ dị vực đánh tan.","thuocTinh":"Phù văn cộng minh","uyLuc":"Có thể làm nứt hư không, cuốn động Hỗn Độn và hiện ra hư ảnh Luân Hồi.","dacDiem":"Dung hội áo nghĩa cùng phù văn của nhiều chủng tộc để hình thành đòn công phạt chung.","congNang":["Hợp nhất phù văn của vạn tộc thành vô thượng kinh văn để công phạt."],"capNhatToi":"@c1307","tabs":{"tienTrinh":[{"chuong":"@c1307","loai":"thi triển","importance":"normal","giaiDoan":"Vạn tộc hợp kích","text":"Phù văn của các tộc cộng minh thành vô thượng kinh văn và gây ra nhiều dị tượng, nhưng bị bàn tay của sinh linh Bất Hủ đánh tan.","anchor":"các tộc ký hiệu hội tụ cùng một chỗ sinh ra đáng sợ cộng minh hình thành vô thượng kinh văn"}]},"nguon":["@c1307"]},{"id":"hac-bach-sinh-tu-quang","name":"Hắc Bạch Sinh Tử Quang","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Sinh tử","soHuu":["Sở Sơn Hà"],"blurb":"Hai luồng thần quang trắng đen được Sở Sơn Hà ôn dưỡng và tế luyện trong cơ thể theo hướng hóa thành binh khí.","detail":"Hắc Bạch Sinh Tử Quang bắt nguồn từ cấm địa sinh mệnh của Cửu Thiên và trở thành bệnh căn kéo dài của Sở Sơn Hà. Trong trận chiến với cường giả Dị Vực, thần quang chặt đứt tích huyết thần hoàn rồi xé nát thân thể đối thủ, nhưng cũng khiến Sở Sơn Hà cạn kiệt tinh khí và ngã xuống.","thuocTinh":"Sinh tử, trắng đen","nguonGoc":"Cấm địa sinh mệnh của Cửu Thiên","yeuCau":"Được Sở Sơn Hà ôn dưỡng và tế luyện trong cơ thể","uyLuc":"Có thể chặt đứt tích huyết thần hoàn và xé nát thân thể cường giả Dị Vực.","dacDiem":"Uy lực lớn nhưng gây tiêu hao nghiêm trọng và gắn với bệnh căn lâu năm của Sở Sơn Hà.","chieuTieuBieu":["Bộc phát hai luồng sáng trắng đen"],"trangThai":"Đang được tế luyện thành binh khí","congNang":["Chặt đứt thần hoàn trói buộc.","Xé nát thân thể đối thủ."],"nguoiTu":[{"ten":"Sở Sơn Hà","tuChuong":"@c1310","tangDatToi":"Ôn dưỡng và tế luyện thành binh khí","trangThai":"Đang tu luyện"}],"capNhatToi":"@c1310","tabs":{"tienTrinh":[{"chuong":"@c1310","loai":"thi triển","importance":"normal","giaiDoan":"Tế luyện thành binh khí","text":"Sở Sơn Hà bộc phát Hắc Bạch Sinh Tử Quang để chặt đứt tích huyết thần hoàn và giết đối thủ, nhưng bản thân cũng cạn kiệt tinh khí.","anchor":"Sơn hà vẫn ở ôn dưỡng cùng tế luyện Hắc Bạch Sinh Tử Quang, muốn đem nó hóa thành binh khí"}]},"nguon":["@c1310"]},{"id":"tich-huyet-than-hoan","name":"Tích huyết thần hoàn","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Huyết","soHuu":["Cường giả Dị Vực mang tích huyết thần hoàn"],"blurb":"Huyết sắc thần hoàn do huyết tinh của nhiều sinh linh bị giết ngưng tụ, vờn quanh thân thể một cường giả Dị Vực.","detail":"Tích huyết thần hoàn có thể hóa thành binh khí để trói và cắt thân thể đối thủ. Trong trận chiến với Sở Sơn Hà, nó khóa chặt thân thể ông nhưng sau đó bị Hắc Bạch Sinh Tử Quang chặt đứt.","thuocTinh":"Huyết","nguonGoc":"Ngưng tụ từ huyết tinh của những sinh linh bị giết","uyLuc":"Có thể hóa thành binh khí trói cứng và cắt thân thể đối thủ.","dacDiem":"Biểu hiện thành vòng sáng đỏ ngòm vờn quanh cơ thể người sử dụng.","trangThai":"Bị chặt đứt","congNang":["Hóa thành binh khí trói cứng đối thủ.","Cắt thân thể đối thủ bằng huyết sắc thần hoàn."],"nguoiTu":[{"ten":"Cường giả Dị Vực mang tích huyết thần hoàn","tuChuong":"@c1310","tangDatToi":"Có thể hóa thần hoàn thành binh khí","trangThai":"Người tu đã tử vong"}],"capNhatToi":"@c1310","tabs":{"tienTrinh":[{"chuong":"@c1310","loai":"thi triển","importance":"normal","giaiDoan":"Hóa thành binh khí","text":"Cường giả Dị Vực hóa tích huyết thần hoàn thành binh khí để trói Sở Sơn Hà, nhưng thần hoàn bị Hắc Bạch Sinh Tử Quang chặt đứt.","anchor":"ở bên ngoài cơ thể vờn quanh vầng sáng màu đỏ ngòm, hóa thành một món binh khí"}]},"nguon":["@c1310"]},{"id":"ba-dao-tien-khi-hoa-dai-dao-chi-hoa","name":"Ba đạo tiên khí hóa đại đạo chi hoa","cn":"","loai":"bi-thuat","loaiLabel":"Tiên cổ pháp","phamCap":"Không rõ","hePhai":"Tiên cổ pháp","soHuu":["Thanh niên vảy hình thoi ở mi tâm"],"blurb":"Phương pháp vận chuyển ba luồng tiên khí thành ba đóa đại đạo chi hoa trên đầu.","detail":"Ba đóa đại đạo chi hoa tuần hoàn ra vào thân thể, qua đó tẩm bổ người tu luyện.","thuocTinh":"Tiên khí","congNang":["Ngưng tụ ba luồng tiên khí thành ba đóa đại đạo chi hoa để tuần hoàn tẩm bổ thân thể."],"nguoiTu":[{"ten":"Thanh niên vảy hình thoi ở mi tâm","tuChuong":"@c1311","tangDatToi":"Ba đạo tiên khí","trangThai":"đang tu luyện"}],"capNhatToi":"@c1311","tabs":{"tienTrinh":[{"chuong":"@c1311","loai":"thi triển","importance":"normal","giaiDoan":"Ba đạo tiên khí","text":"Thanh niên vảy hình thoi vận chuyển ba luồng tiên khí thành ba đóa đại đạo chi hoa để tẩm bổ thân thể.","anchor":"ba đóa đại đạo bông hoa đều là do ba đạo tiên khí ngưng tụ mà thành"}]},"nguon":["@c1311"]},{"id":"tam-loai-phap-an-cua-bat-ti-thuong-nhan","name":"Tám loại pháp ấn của Bát Tí Thượng Nhân","cn":"","loai":"than-thong","loaiLabel":"Thần thông chiến đấu","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Bát Tí Thượng Nhân"],"blurb":"Thần thông cho phép Bát Tí Thượng Nhân đồng thời kết tám loại pháp ấn bằng tám cánh tay.","detail":"Tám pháp ấn tạo nên mật độ công kích cao và có thể đối kháng trực diện với Phần Thiên chi hỏa của Đại Phần Thiên Công.","congNang":["Dùng tám cánh tay đồng thời kết các pháp ấn khác nhau để công kích."],"uyLuc":"Có thể đối kháng trực diện với Đại Phần Thiên Công do Xích Phát Thần Quân thi triển.","nguoiTu":[{"ten":"Bát Tí Thượng Nhân","tuChuong":"@c1311","tangDatToi":"Đồng thời vận dụng tám pháp ấn","trangThai":"đang sử dụng"}],"capNhatToi":"@c1311","tabs":{"tienTrinh":[{"chuong":"@c1311","loai":"thi triển","importance":"normal","giaiDoan":"Tám ấn đồng xuất","text":"Bát Tí Thượng Nhân dùng tám cánh tay đồng thời kết các pháp ấn khác nhau để đối kháng Phần Thiên chi hỏa.","anchor":"tám đầu cánh tay tề động, tất cả niết bất đồng pháp ấn"}]},"nguon":["@c1311"]},{"id":"thuat-tra-xet-co-chung","name":"Thuật tra xét cổ chủng","cn":"","loai":"bi-thuat","loaiLabel":"Bí thuật","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":[],"blurb":"Bí thuật giúp tu sĩ dị vực phát hiện cổ chủng hoặc hạt giống nằm trong cơ thể đối phương.","detail":"Thủ đoạn này được truyền lại từ thời Tiên cổ để nhận biết người nắm giữ hoàn mỹ hạt giống, đồng thời cho thấy dị vực đã nghiên cứu phương pháp đối phó những cổ chủng ấy.","thuocTinh":"Tra xét","nguonGoc":"Dị vực, truyền từ thời Tiên cổ","uyLuc":"Có thể nhìn ra cổ chủng ẩn trong cơ thể đối phương.","dacDiem":"Được dùng để lựa chọn và đối phó người mang hạt giống mạnh.","congNang":["Phát hiện cổ chủng hoặc hạt giống trong cơ thể đối phương."],"capNhatToi":"@c1312","tabs":{"tienTrinh":[{"chuong":"@c1312","loai":"xuất hiện","importance":"normal","giaiDoan":"Lộ diện","text":"Tu sĩ dị vực bộc lộ khả năng tra xét cổ chủng trong cơ thể các đối thủ phía Cửu Thiên Thập Địa.","anchor":"dị vực tu sĩ có thủ đoạn đặc thù, có thể tra xét cổ chủng"}]},"nguon":["@c1312"]},{"id":"than-phap-loi-dien-cua-thach-hao","name":"Thân pháp lôi điện của Thạch Hạo","cn":"","loai":"than-thong","loaiLabel":"Thân pháp","phamCap":"Không rõ","hePhai":"Lôi điện","soHuu":["Thạch Hạo"],"blurb":"Thân pháp giúp Thạch Hạo hóa thành hồ quang điện và rời khỏi vị trí trong nháy mắt.","detail":"Thạch Hạo thi triển thân pháp này để tránh đòn hợp kích từ hơn mười Vương giả dị vực. Tốc độ dịch chuyển giúp hắn thoát khỏi vị trí bị hàng loạt bảo thuật đồng thời khóa đánh.","thuocTinh":"Lôi điện","congNang":["Hóa người thi triển thành hồ quang điện để nhanh chóng rời vị trí và né đòn hợp kích."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1313","tangDatToi":"","trangThai":"thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c1313","loai":"thi triển","importance":"normal","giaiDoan":"Né hợp kích","text":"Thạch Hạo hóa thành hồ quang điện, biến mất khỏi vị trí cũ và tránh được đòn hợp kích của quần vương dị vực.","anchor":"Thạch Hạo hóa thành một đạo hồ quang điện, theo tại chỗ biến mất"}]},"capNhatToi":"@c1313","nguon":["@c1313"]},{"id":"ba-dao-tien-khi-cua-huyen-con","name":"Ba đạo tiên khí của Huyền Côn","cn":"","loai":"cong-phap","loaiLabel":"Pháp môn tu luyện","phamCap":"","hePhai":"","soHuu":["Huyền Côn"],"blurb":"Pháp môn tiên khí của Huyền Côn, có thể hóa thành thần kiếm và vận hành tuần hoàn đại đạo trong cơ thể.","detail":"Ba đạo tiên khí hiện thành ba đóa đại đạo chi hoa trên đầu Huyền Côn và hóa thành ba thanh thần kiếm tấn công Xà Dạ Xoa.","congNang":["Hóa thành ba thanh thần kiếm để công kích.","Tạo vòng tuần hoàn tiên khí và hiển hóa ba đóa đại đạo chi hoa."],"nguoiTu":[{"ten":"Huyền Côn","tuChuong":"@c1314","tangDatToi":"Ba đạo tiên khí","trangThai":"đã tu thành"}],"tabs":{"tienTrinh":[{"chuong":"@c1314","loai":"thi triển","importance":"normal","giaiDoan":"Ba đạo tiên khí","text":"Huyền Côn hóa ba đạo tiên khí thành ba thanh thần kiếm để tấn công Xà Dạ Xoa.","anchor":"ba đạo tiên khí hóa thành ba thanh thần kiếm"}]},"capNhatToi":"@c1314","nguon":["@c1314"]},{"id":"da-xoa-si-tuyet-hoc","name":"Dạ Xoa sí tuyệt học","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Xà Dạ Xoa","soHuu":["Xà Dạ Xoa"],"blurb":"Tuyệt học phát động từ đôi cánh bạc của Xà Dạ Xoa, tạo sức mạnh hủy diệt và giam cầm đối thủ.","detail":"Phù văn từ đôi cánh bạc phá nát hư không, tạo ra các dị tượng hủy diệt và nhấn chìm Huyền Côn trước đòn kết liễu.","uyLuc":"Khi luyện đến cảnh giới cao thâm, tuyệt học có thể phá tinh không.","congNang":["Phá nát hư không bằng phù văn phát ra từ đôi cánh bạc.","Giam cầm đối thủ trong sức mạnh hủy diệt."],"nguoiTu":[{"ten":"Xà Dạ Xoa","tuChuong":"@c1314","tangDatToi":"","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1314","loai":"thi triển","importance":"normal","giaiDoan":"Tuyệt học cánh bạc","text":"Xà Dạ Xoa phát động phù văn từ đôi cánh bạc, phá hư không và giam cầm Huyền Côn.","anchor":"Đây là Xà Dạ Xoa tuyệt học, luyện đến cảnh giới cao thâm"}]},"capNhatToi":"@c1314","nguon":["@c1314"]},{"id":"khoi-xam-ho-the-cua-xa-da-xoa","name":"Khói xám hộ thể của Xà Dạ Xoa","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Xà Dạ Xoa","soHuu":["Xà Dạ Xoa"],"blurb":"Lớp khói xám bao phủ thân thể và đuôi Xà Dạ Xoa, gia cố chúng đến mức có thể chống lại tiên khí.","detail":"Khói xám giúp thân thể Xà Dạ Xoa chống đỡ thần kiếm do ba đạo tiên khí hóa thành cùng các pháp ấn và bảo thuật của Huyền Côn.","dacDiem":"Khói xám có thể so với tiên khí.","congNang":["Gia cố thân thể và đuôi để chống lại thần kiếm, pháp ấn và bảo thuật."],"nguoiTu":[{"ten":"Xà Dạ Xoa","tuChuong":"@c1314","tangDatToi":"","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1314","loai":"thi triển","importance":"normal","giaiDoan":"Khói xám hộ thể","text":"Xà Dạ Xoa dùng khói xám gia cố thân thể, chống lại các đòn đánh của Huyền Côn.","anchor":"những kia khói xám rất đặc biệt, có thể so với tiên khí"}]},"capNhatToi":"@c1314","nguon":["@c1314"]},{"id":"bon-mang-ma-am-cua-hoang-kim-ma-dieu","name":"Bổn mạng Ma Âm của Hoàng Kim Ma Điểu","cn":"","loai":"than-thong","loaiLabel":"Thần thông bổn mạng","phamCap":"Không rõ","hePhai":"Hoàng Kim Ma Điểu nhất tộc","soHuu":["Hoàng Kim Ma Điểu"],"blurb":"Bổn mạng Ma Âm là thần thông âm thanh của Hoàng Kim Ma Điểu, có khả năng phá nhịp thi triển bảo thuật và trực tiếp công kích thần hồn, Nguyên Thần. Trong lần thể hiện mạnh nhất, Ma Âm đã xuyên thủng mi tâm Lữ Hồng.","detail":"Hoàng Kim Ma Điểu thi triển tiếng kêu bổn mạng để làm gián đoạn bảo thuật của đối phương, đồng thời liên tục gây tổn thương lên thần hồn. Khi được phát động với uy lực mạnh nhất, Ma Âm xuyên thủng mi tâm Lữ Hồng. @c1315","thuocTinh":"Âm thanh, thần hồn","uyLuc":"Lần thi triển mạnh nhất xuyên thủng mi tâm Lữ Hồng. @c1315","dacDiem":"Là tiếng kêu bổn mạng có khả năng phá nhịp thi triển bảo thuật và công kích Nguyên Thần.","chieuTieuBieu":"Ma Âm bổn mạng","trangThai":"Đang được Hoàng Kim Ma Điểu sử dụng","congNang":["Làm gián đoạn bảo thuật của đối phương. @c1315","Công kích, gây tổn thương thần hồn và Nguyên Thần. @c1315","Có thể xuyên thủng mi tâm mục tiêu khi phát động ở uy lực mạnh nhất. @c1315"],"nguoiTu":[{"ten":"Hoàng Kim Ma Điểu","tuChuong":"@c1315","tangDatToi":"Thi triển bổn mạng","trangThai":"Đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c1315","loai":"thi triển","importance":"major","giaiDoan":"Hiện nguyên hình phát động Ma Âm mạnh nhất","text":"Hoàng Kim Ma Điểu dùng Ma Âm làm gián đoạn bảo thuật, liên tục tổn thương thần hồn Lữ Hồng và cuối cùng xuyên thủng mi tâm nàng.","anchor":"Chỉ là minh thanh mà thôi, lại để cho nhân bảo thuật gián đoạn"}]},"capNhatToi":"@c1315","nguon":["@c1315"]},{"id":"co-chu-quay-nhieu-co-chung","name":"Cổ chú quấy nhiễu cổ chủng","cn":"","loai":"bi-thuat","loaiLabel":"Chú thuật","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Đường Ngô"],"blurb":"Cổ chú do Đường Ngô dùng thần niệm ngâm tụng để khắc chế cổ chủng hoàn mỹ.","detail":"Chú thuật làm suy yếu uy thế của Hồng Mông Tử Khí chủng và từng suýt cắt đứt liên hệ giữa cổ chủng với Tử Nhật Thiên Quân.","thuocTinh":"Quấy nhiễu cổ chủng","uyLuc":"Có thể làm suy yếu uy thế và suýt cắt đứt liên hệ giữa tu sĩ với cổ chủng hoàn mỹ.","congNang":["Quấy nhiễu uy thế của cổ chủng hoàn mỹ.","Làm suy yếu liên hệ giữa cổ chủng và người dung hợp."],"nguoiTu":[{"ten":"Đường Ngô","tuChuong":"@c1316","tangDatToi":"Không rõ","trangThai":"đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c1316","loai":"thi triển","importance":"normal","giaiDoan":"Khắc chế cổ chủng","text":"Đường Ngô ngâm tụng cổ chú để làm nhiễu Hồng Mông Tử Khí chủng và liên hệ của cổ chủng với Tử Nhật Thiên Quân.","anchor":"ngâm tụng một loại cổ chú ngữ, rõ ràng có thể làm nhiễu không rảnh cổ chủng uy thế"}]},"capNhatToi":"@c1316","nguon":["@c1316"]},{"id":"o-quang-ban-menh-cua-duong-ngo","name":"Ô quang bản mệnh của Đường Ngô","cn":"","loai":"bi-thuat","loaiLabel":"Bản mệnh bí thuật","phamCap":"Không rõ","hePhai":"Đường Ngô tộc","soHuu":["Đường Ngô"],"blurb":"Bản mệnh bí thuật của Đường Ngô có khả năng ăn mòn vạn vật.","detail":"Ô quang làm hư không sụp đổ và thời gian hỗn loạn, qua đó áp chế Tử Nhật Thiên Quân trong trận quyết đấu.","thuocTinh":"Ăn mòn","uyLuc":"Ăn mòn vạn vật, làm sụp hư không và nhiễu loạn thời gian.","congNang":["Ăn mòn vạn vật.","Làm hư không sụp đổ và thời gian hỗn loạn."],"nguoiTu":[{"ten":"Đường Ngô","tuChuong":"@c1316","tangDatToi":"Không rõ","trangThai":"đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c1316","loai":"thi triển","importance":"normal","giaiDoan":"Áp chế Tử Nhật Thiên Quân","text":"Đường Ngô thi triển ô quang bản mệnh để ăn mòn vạn vật và áp chế Tử Nhật Thiên Quân.","anchor":"đây là bổn mạng của nó bí thuật, cái loại nầy quang ăn mòn vạn vật"}]},"capNhatToi":"@c1316","nguon":["@c1316"]},{"id":"to-thuat-ma-tuong","name":"Tổ thuật ma tường","cn":"","loai":"bi-thuat","loaiLabel":"Tổ thuật","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Quái nhân mười hai cánh tay"],"blurb":"Tổ thuật gia truyền triệu hồi một bức ma tường đen nhuộm máu để áp chế đối thủ.","detail":"Sức mạnh của ma tường được tích lũy qua nhiều đời tổ tiên từng sát phạt Chí Cường giả. Truyền thừa càng lâu thì uy lực càng lớn, nhưng hậu duệ phải tự lĩnh ngộ mới có thể kích phát.","thuocTinh":"Sát phạt và áp chế","nguonGoc":"Tổ thuật được tích lũy từ những cuộc sát phạt qua các đời kể từ Tiên cổ.","yeuCau":"Hậu duệ phải tự lĩnh ngộ để kích phát.","uyLuc":"Có thể triệu hồi ma tường đen nhuộm máu từ trên cao áp chế đối thủ.","dacDiem":"Uy lực tăng theo thời gian truyền thừa và chiến tích sát phạt của các đời tổ tiên.","congNang":["Triệu hồi ma tường đen nhuộm máu để trấn áp đối thủ."],"nguoiTu":[{"ten":"Quái nhân mười hai cánh tay","tuChuong":"@c1319","tangDatToi":"Có thể triệu hồi ma tường","trangThai":"tu-vong"}],"tabs":{"tienTrinh":[{"chuong":"@c1319","loai":"thi triển","importance":"normal","giaiDoan":"Triệu hồi rồi bị phá","text":"Quái nhân mười hai cánh tay triệu hồi ma tường đen để áp chế Thạch Hạo, nhưng bức tường bị các bí thuật phối hợp phá hủy.","anchor":"một bức màu đen ma tường, mặt trên nhiễm đầy vết máu, đen kịt bên trong mang theo huyết châu, áp chế mà xuống"}]},"trangThai":"Đã bị phá trong lần thi triển tại @c1319","capNhatToi":"@c1319","nguon":["@c1319"]},{"id":"to-tien-tinh-huyet-duong-ngo","name":"Tổ tiên tinh huyết của Đường Ngô","cn":"","loai":"bi-thuat","loaiLabel":"Bí bảo hồi phục","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Đường Ngô"],"blurb":"Một giọt tinh huyết tổ tiên được phong ấn trong thủy tinh, có khả năng tái tạo thân thể và phục hồi toàn diện.","detail":"Đường Ngô uống giọt tinh huyết sau khi thân thể bị xé đứt. Sức mạnh trong tinh huyết giúp hắn mọc lại phần thân bị mất và khôi phục tinh khí thần lên trạng thái đỉnh cao.","thuocTinh":"Tái sinh và hồi phục","nguonGoc":"Tinh huyết do tổ tiên của Đường Ngô để lại.","uyLuc":"Tái tạo phần thân thể bị mất và phục hồi đồng thời tinh khí thần.","dacDiem":"Được phong ấn trong thủy tinh dưới dạng chất lỏng đỏ sẫm.","congNang":["Tái tạo thân thể bị tổn hại.","Khôi phục toàn diện tinh khí thần lên trạng thái đỉnh cao."],"nguoiTu":[{"ten":"Đường Ngô","tuChuong":"@c1319","tangDatToi":"Đã sử dụng một giọt","trangThai":"tu-vong"}],"tabs":{"tienTrinh":[{"chuong":"@c1319","loai":"xuất hiện","importance":"normal","giaiDoan":"Tái tạo thân thể","text":"Đường Ngô uống tổ tiên tinh huyết để tái sinh phần thân bị mất và khôi phục toàn diện tinh khí thần.","anchor":"tổ tiên tinh huyết... đoạn thể cấp tốc sinh trưởng, này không phải đơn giản tái tạo thân thể, mà là tinh khí thần toàn phương vị khôi phục"}]},"trangThai":"Đã được Đường Ngô sử dụng tại @c1319","capNhatToi":"@c1319","nguon":["@c1319"]},{"id":"suc-manh-ten-that-cua-an-lan","name":"Sức mạnh tên thật của An Lan","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Uy năng của tồn tại vô thượng","hePhai":"An Lan tộc","soHuu":["Tồn tại vô thượng họ An Lan"],"blurb":"Uy năng khiến binh khí, sát khí và một phần sức mạnh của tồn tại vô thượng họ An Lan hiển hiện khi dòng họ được hô gọi như tên thật.","detail":"Khi Thạch Hạo nói tới họ An Lan, sát khí bùng lên và một cây trường thương vàng xuất hiện giữa hư không. Đại trưởng lão nhận định hiện tượng này chứng tỏ tồn tại vô thượng kia vẫn còn sống.","thuocTinh":"Uy năng tên thật","yeuCau":"Tên thật hoặc dòng họ An Lan được hô gọi","uyLuc":"Có thể triệu hiện một phần binh khí và sức mạnh của tồn tại vô thượng.","dacDiem":"Uy năng tự hiển hiện từ lời gọi tên mà không cần bản thể trực tiếp giáng lâm.","congNang":["Hiển hiện binh khí, sát khí và một phần sức mạnh khi tên thật hoặc dòng họ An Lan được gọi tại @c1320."],"nguoiTu":[{"ten":"Tồn tại vô thượng họ An Lan","tuChuong":"@c1320","tangDatToi":"Không nêu","trangThai":"Còn sống"}],"trangThai":"Đang tồn tại","capNhatToi":"@c1320","tabs":{"tienTrinh":[{"chuong":"@c1320","loai":"xuất hiện","importance":"normal","giaiDoan":"Uy năng tên thật hiển hiện","text":"Tên An Lan làm cây trường thương vàng cùng một phần sức mạnh của tồn tại vô thượng hiển hiện.","anchor":"hô hoán hắn dòng họ, như cùng ở tại hoán tên thật của hắn, binh khí cùng sức mạnh các loại liền có thể hiển hiện bộ phận"}]},"nguon":["@c1320"]},{"id":"to-thuat-an-lan","name":"Tổ thuật An Lan","cn":"","loai":"than-thong","loaiLabel":"Tổ thuật huyết mạch","phamCap":"Không rõ","hePhai":"An Lan tộc","soHuu":["Triển Phong"],"blurb":"Tổ thuật huyết mạch của An Lan tộc, được Triển Phong dùng để triệu ra hàng vạn trường thương màu vàng.","detail":"Triển Phong vận dụng tổ thuật gọi ra hàng vạn trường thương vàng xuyên thủng hư không. Thế công bị Bảo thuật Lôi Đế phá hủy một phần, sau đó toàn bộ số trường thương còn lại bị duy nhất động thiên của Thạch Hạo nghiền nát.","thuocTinh":"Huyết mạch","nguonGoc":"An Lan tộc","uyLuc":"Có thể triệu ra hàng vạn trường thương màu vàng tạo thành thế công quy mô lớn.","dacDiem":"Các trường thương là biểu hiện của tổ thuật, không phải binh khí thông thường.","congNang":["Triệu hồi hàng vạn trường thương màu vàng xuyên thủng hư không."],"nguoiTu":[{"ten":"Triển Phong","tuChuong":"@c1321","tangDatToi":"Có thể triệu ra hàng vạn trường thương","trangThai":"tu-vong"}],"trangThai":"Được Triển Phong thi triển tại @c1321","capNhatToi":"@c1321","tabs":{"tienTrinh":[{"chuong":"@c1321","loai":"thi triển","importance":"normal","giaiDoan":"Triển Phong vận dụng","text":"Triển Phong triệu ra hàng vạn trường thương vàng, nhưng thế công bị Thạch Hạo phá hủy.","anchor":"Đó không phải bình thường binh khí, mà là tổ thuật thể hiện, là một loại đại uy năng hiện ra!"}]},"dinhDanh":"goc","nguon":["@c1321"]},{"id":"truong-thuong-chan-huyet-an-lan","name":"Trường thương chân huyết An Lan","cn":"","loai":"than-thong","loaiLabel":"Thần thông huyết mạch","phamCap":"Không rõ","hePhai":"An Lan tộc","soHuu":["Triển Phong"],"blurb":"Thần thông biến hoa văn trường thương trên cánh tay người mang huyết mạch An Lan thành một cây trường thương vàng.","detail":"Triển Phong kích hoạt hoa văn trên cánh tay, khiến nó ly thể và hóa thành trường thương vàng có tốc độ cùng uy lực lớn. Thạch Hạo dùng hai tay được Bất Diệt Kinh gia trì bắt lấy rồi bẻ gãy trường thương, làm hình xăm biến mất và chân huyết của Triển Phong bị phá hỏng.","thuocTinh":"Huyết mạch An Lan","nguonGoc":"Sức mạnh do chân huyết An Lan thai nghén","uyLuc":"Cây trường thương vàng do chân huyết thai nghén có sức mạnh kinh khủng, nhưng bị đôi tay gia trì bởi Bất Diệt Kinh bẻ gãy.","dacDiem":"Huyết thống càng tinh khiết thì sức mạnh nhận được từ hoa văn trường thương càng lớn.","congNang":["Biến hoa văn huyết mạch trên cánh tay thành trường thương vàng để công kích."],"nguoiTu":[{"ten":"Triển Phong","tuChuong":"@c1321","tangDatToi":"Kích hoạt được trường thương từ một phần tư chân huyết An Lan","trangThai":"tu-vong"}],"trangThai":"Bị phá tại @c1321","capNhatToi":"@c1321","tabs":{"tienTrinh":[{"chuong":"@c1321","loai":"thi triển","importance":"normal","giaiDoan":"Trường thương bị bẻ gãy","text":"Triển Phong hóa hoa văn huyết mạch thành trường thương vàng, nhưng Thạch Hạo bắt lấy và bẻ gãy nó.","anchor":"Thuộc về An Lan chân huyết sức mạnh, dựng dục ra cây trường thương, phát huy ra không thể nào tưởng tượng được sức mạnh kinh khủng!"}]},"dinhDanh":"goc","nguon":["@c1321"]},{"id":"hoa-dao-cua-hoa-nham-vuong","name":"Hỏa đạo của Hỏa Nham Vương","cn":"","loai":"than-thong","loaiLabel":"Thần thông chủng tộc","phamCap":"Không rõ","hePhai":"Hỏa nham Vương tộc","soHuu":["Hỏa Nham Vương"],"blurb":"Thần thông hỏa đạo giúp Hỏa Nham Vương dung nhập biển dung nham, khống chế hỏa mạch và tiếp dẫn sức mạnh mặt trời.","detail":"Hỏa Nham Vương dùng hỏa đạo nung chảy đại địa thành biển dung nham, hòa chân thân vào đó để ẩn nấp và khiến hư không sụp đổ. Thần thông còn cho phép câu thông thiên địa, triệu hoán Thái Dương chi tinh để nung luyện vạn vật.","thuocTinh":"Hỏa","congNang":["Dung nhập và khống chế biển dung nham.","Che giấu chân thân trong dung nham.","Câu thông thiên địa để tiếp dẫn Thái Dương chi tinh."],"uyLuc":"Có thể nung chảy đại địa, đốt sụp hư không và huy động sức mạnh của Thái Dương chi tinh.","dacDiem":"Gắn với năng lực khống hỏa trời sinh của Hỏa nham Vương tộc.","nguoiTu":[{"ten":"Hỏa Nham Vương","tuChuong":"@c1323","tangDatToi":"Có thể dung nhập dung nham và tiếp dẫn Thái Dương chi tinh","trangThai":"đã thi triển"}],"trangThai":"Đã xuất hiện","capNhatToi":"@c1323","tabs":{"tienTrinh":[{"chuong":"@c1323","loai":"thi triển","importance":"normal","giaiDoan":"Khống chế biển dung nham","text":"Hỏa Nham Vương thi triển hỏa đạo để dung nhập biển dung nham và triệu hoán Thái Dương chi tinh đối phó Thạch Hạo.","anchor":"Hỏa nham vương câu thông thiên địa, triệu hoán đến rồi Thái Dương chi tinh sức mạnh to lớn"}]},"nguon":["@c1323"]},{"id":"quang-am-chi-ca","name":"Quang ám chi ca","cn":"","loai":"bi-thuat","loaiLabel":"Cổ thuật quang ám","phamCap":"Không rõ","hePhai":"Song Tử Vương tộc","soHuu":["Song Tử Vương"],"blurb":"Cổ thuật do hai đầu của Song Tử Vương đồng thời thi triển, khiến sức mạnh quang và ám xuất hiện rồi va chạm.","detail":"Quang ám chi ca kết hợp hai sức mạnh đối lập để tạo màn sáng, bão táp tử vong và sức hủy diệt trong chiến đấu.","thuocTinh":"Quang và ám","uyLuc":"Sự va chạm giữa quang và ám phát sinh sức hủy diệt.","dacDiem":"Được hai đầu của Song Tử Vương phối hợp ngâm tụng.","chieuTieuBieu":["Quang ám chi ca"],"congNang":["Kết hợp sức mạnh quang và ám thành công kích hủy diệt."],"nguoiTu":[{"ten":"Song Tử Vương","tuChuong":"@c1324","tangDatToi":"Có thể thi triển","trangThai":"tu-vong"}],"trangThai":"Đã xuất hiện","capNhatToi":"@c1324","tabs":{"tienTrinh":[{"chuong":"@c1324","loai":"thi triển","importance":"normal","giaiDoan":"Giao chiến với Thạch Hạo","text":"Song Tử Vương dùng hai đầu ngâm bí ngôn, phối hợp sức mạnh quang và ám để tạo công kích hủy diệt.","anchor":"Quang ám chi ca, vang vọng đất trời!"}]},"nguon":["@c1324"]},{"id":"than-chu-quay-nhieu-hoan-my-co-chung","name":"Thần chú quấy nhiễu hoàn mỹ cổ chủng","cn":"","loai":"bi-thuat","loaiLabel":"Bí thuật dị vực","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Song Tử Vương"],"blurb":"Bí thuật do dị vực nghiên cứu qua nhiều năm nhằm khắc chế người dung hợp hoàn mỹ cổ chủng.","detail":"Khi Song Tử Vương ngâm thần chú, hoàn mỹ hạt giống trong cơ thể Lam Tiên và những người quan chiến xao động nghiêm trọng. Bí thuật còn được dùng để thăm dò Thạch Hạo có dung hợp cổ chủng hay không.","thuocTinh":"Quấy nhiễu đạo chủng","nguonGoc":"Thành quả nghiên cứu lâu năm của dị vực.","uyLuc":"Có thể khiến hoàn mỹ cổ chủng trong cơ thể người tu hành xao động và chịu ảnh hưởng rõ rệt.","dacDiem":"Vừa khắc chế hoàn mỹ cổ chủng vừa có thể dùng để thăm dò người dung hợp đạo chủng.","congNang":["Quấy nhiễu hoàn mỹ cổ chủng trong cơ thể người tu hành.","Thăm dò mục tiêu có dung hợp hoàn mỹ cổ chủng hay không."],"nguoiTu":[{"ten":"Song Tử Vương","tuChuong":"@c1324","tangDatToi":"Có thể thi triển","trangThai":"tu-vong"}],"trangThai":"Đã xuất hiện","capNhatToi":"@c1324","tabs":{"tienTrinh":[{"chuong":"@c1324","loai":"thi triển","importance":"normal","giaiDoan":"Thăm dò Thạch Hạo","text":"Song Tử Vương ngâm thần chú, khiến hoàn mỹ cổ chủng của những người quan chiến xao động và dùng phản ứng đó để thăm dò Thạch Hạo.","anchor":"Song Tử Vương ngâm tụng thần chú, là dị vực như thế bao năm tháng qua nghiên cứu tâm đắc, có thể quấy rầy hoàn mỹ cổ chủng!"}]},"nguon":["@c1324"]},{"id":"truong-vuc-canh-bac-cua-xa-da-xoa","name":"Trường vực cánh bạc của Xà Dạ Xoa","cn":"","loai":"than-thong","loaiLabel":"Thần thông chủng tộc","phamCap":"Không rõ","hePhai":"Xà Dạ Xoa tộc","soHuu":["Xà Dạ Xoa"],"blurb":"Thần thông dùng đôi cánh bạc khuấy động cuồng phong, phá hư không và tạo trường vực hạn chế đối phương.","detail":"Trường vực có thể cầm cố và làm chậm hành động của mục tiêu. Khi đối đầu Thạch Hạo, hiệu quả cầm cố chỉ duy trì trong chốc lát trước khi bị phá.","thuocTinh":"Không gian và cầm cố","uyLuc":"Cuồng phong từ cánh bạc có thể thổi vỡ hư không và hình thành trường vực.","dacDiem":"Dùng đôi cánh bạc làm trung tâm phát động.","congNang":["Tạo cuồng phong phá hư không.","Hình thành trường vực cầm cố và làm chậm mục tiêu."],"nguoiTu":[{"ten":"Xà Dạ Xoa","tuChuong":"@c1324","tangDatToi":"Có thể thi triển","trangThai":"tu-vong"}],"trangThai":"Đã xuất hiện","capNhatToi":"@c1324","tabs":{"tienTrinh":[{"chuong":"@c1324","loai":"thi triển","importance":"normal","giaiDoan":"Tái chiến với Thạch Hạo","text":"Xà Dạ Xoa dùng cánh bạc tạo cuồng phong và trường vực để cầm cố Thạch Hạo, nhưng hiệu quả nhanh chóng bị phá.","anchor":"không chỉ có thổi nát hư không, hơn nữa hình thành tràng vực, cầm cố mấy người hành động"}]},"nguon":["@c1324"]},{"id":"long-vu-nhu-thien-tien","name":"Lông vũ như Thiên tiễn","cn":"","loai":"than-thong","loaiLabel":"Tổ thuật","phamCap":"Không rõ","hePhai":"Tộc Hoàng Kim Ma Điểu","soHuu":["Hoàng Kim Ma Điểu"],"blurb":"Thiên phú biến mười vạn lông bản thể thành thần tiễn phủ kín chiến trường và xuyên thủng hư không.","detail":"Hoàng Kim Ma Điểu thiêu đốt lông vàng, biến chúng thành mười vạn thần tiễn cuồng bạo. Thạch Hạo dùng vòng xoáy lôi đình nuốt và phá hủy toàn bộ đòn đánh.","thuocTinh":"Hoàng kim thần vũ","uyLuc":"Mười vạn thần vũ có thể phủ kín chiến trường và xuyên thủng hư không.","dacDiem":"Dùng lông bản thể làm thần tiễn.","chieuTieuBieu":"Mười vạn lông vũ hóa Thiên tiễn","congNang":["Phóng mười vạn thần vũ xuyên thủng hư không."],"nguoiTu":[{"ten":"Hoàng Kim Ma Điểu","tuChuong":"@c1325","tangDatToi":"Có thể phóng mười vạn thần vũ","trangThai":"đã thi triển"}],"trangThai":"Được thi triển trong tử chiến","capNhatToi":"@c1325","tabs":{"tienTrinh":[{"chuong":"@c1325","loai":"thi triển","importance":"normal","giaiDoan":"Mười vạn thần vũ","text":"Hoàng Kim Ma Điểu biến mười vạn lông bản thể thành thần tiễn phủ kín chiến trường, nhưng toàn bộ bị vòng xoáy lôi đình của Thạch Hạo phá hủy.","anchor":"Đây là Hoàng Kim Ma Điểu thiên phú bản lĩnh, lông vũ như Thiên tiễn, đầy đủ thập vạn chiếc, che ngợp bầu trời, cuồng bạo cực kỳ"}]},"nguon":["@c1325"]},{"id":"ma-dieu-mot-de-thien-ha-than-thuong","name":"Ma điểu một đề, thiên hạ thần thương","cn":"","loai":"than-thong","loaiLabel":"Tổ thuật","phamCap":"Tổ thuật nổi danh của tộc Hoàng Kim Ma Điểu","hePhai":"Tộc Hoàng Kim Ma Điểu","soHuu":["Hoàng Kim Ma Điểu"],"blurb":"Ma điểu một đề, thiên hạ thần thương là Tổ thuật ma âm của Hoàng Kim Ma Điểu, chuyên chém thần hồn và thiêu đốt nguyên thần. Khi thiêu đốt Tổ huyết cùng sinh mệnh bản nguyên để liên tiếp phát ra chín tiếng ma âm, thuật này tạo thành sát cục đủ uy hiếp sinh linh đồng cấp.","detail":"Hoàng Kim Ma Điểu từng thi triển thuật này bằng cách thiêu đốt Tổ huyết và sinh mệnh bản nguyên, liên tiếp phát ra chín tiếng ma âm tác động trực tiếp lên thần hồn. Chín âm gợn sóng giao hòa thành sát cục; trong trận chiến với Thạch Hạo, chúng khiến mi tâm hắn nứt ra và chảy máu, nhưng cuối cùng bị Nguyên Thủy Chân Giải hóa giải. @c1325","thuocTinh":"Công kích thần hồn","yeuCau":"Có thể phải thiêu đốt Tổ huyết và sinh mệnh bản nguyên khi liên phát tới chín tiếng.","uyLuc":"Chín âm gợn sóng giao hòa thành sát cục đủ uy hiếp đối thủ đồng cấp.","dacDiem":"Cực hạn thi triển đòi hỏi Hoàng Kim Ma Điểu thiêu đốt Tổ huyết và sinh mệnh bản nguyên để liên tiếp phát ra chín tiếng ma âm. @c1325","chieuTieuBieu":"Chín tiếng ma âm","congNang":["Chém thần hồn và thiêu đốt nguyên thần của mục tiêu.","Dùng chín âm gợn sóng giao hòa để tạo thành sát cục đủ sức uy hiếp sinh linh đồng cấp. @c1325"],"nguoiTu":[{"ten":"Hoàng Kim Ma Điểu","tuChuong":"@c1325","tangDatToi":"Liên phát chín tiếng","trangThai":"đã thi triển cực hạn"}],"trangThai":"Được thi triển với đại giá sinh mệnh","capNhatToi":"@c1325","tabs":{"tienTrinh":[{"chuong":"@c1325","loai":"hé lộ tầng-chiêu","importance":"major","giaiDoan":"Chín tiếng ma âm","text":"Hoàng Kim Ma Điểu thiêu đốt Tổ huyết và sinh mệnh bản nguyên để liên phát chín tiếng ma âm, đẩy nguyên thần Thạch Hạo vào sát cục.","anchor":"Hoàng Kim Ma Điểu kêu to, vận dụng tộc này nổi danh nhất Tổ thuật, ma điểu một đề, thiên hạ thần thương!"}]},"nguon":["@c1325"]},{"id":"long-quy-trao","name":"Long Quy trảo","cn":"","loai":"than-thong","loaiLabel":"Thiên phú huyết mạch","phamCap":"Không rõ","hePhai":"Kim Giáp tộc","soHuu":["Cao thủ trẻ tuổi Kim Giáp Vương tộc"],"blurb":"Thiên phú huyết mạch thể hiện qua móng vuốt Long Quy, có thể xé rách hư không và phóng hàn mang.","detail":"Cao thủ trẻ tuổi Kim Giáp Vương tộc dùng móng vuốt sắc bén xé hư không để phát động nhiều đạo hàn mang tấn công Thạch Hạo.","thuocTinh":"Huyết mạch Long Quy","congNang":["Xé hư không và phát ra nhiều đạo hàn mang công kích."],"nguoiTu":[{"ten":"Cao thủ trẻ tuổi Kim Giáp Vương tộc","tuChuong":"@c1327","tangDatToi":"Có thể thi triển","trangThai":"tu-vong"}],"tabs":{"tienTrinh":[{"chuong":"@c1327","loai":"thi triển","importance":"normal","giaiDoan":"Giao chiến với Thạch Hạo","text":"Cao thủ Kim Giáp tộc dùng Long Quy trảo xé hư không và phóng hàn mang tấn công.","anchor":"Kim Giáp tộc cao thủ móng vuốt sắc bén, là Long Quy móng vuốt, xé ra hư không"}]},"capNhatToi":"@c1327","nguon":["@c1327"]},{"id":"to-thuat-kim-giap-toc","name":"Tổ thuật Kim Giáp tộc","cn":"","loai":"than-thong","loaiLabel":"Tổ thuật","phamCap":"Không rõ","hePhai":"Kim Giáp tộc","soHuu":["Cao thủ trẻ tuổi Kim Giáp Vương tộc"],"blurb":"Tổ thuật của Kim Giáp tộc kết hợp sức phòng ngự của giáp xác với phù văn công kích.","detail":"Người thi triển thu tứ chi và đầu vào mai rùa hoàng kim, dùng giáp xác va chạm và phóng chùm sáng phù văn xuyên trời.","thuocTinh":"Công thủ hợp nhất","congNang":["Thu toàn thân vào giáp xác để phòng thủ.","Dùng phù văn trên mai rùa va chạm và phóng chùm sáng công kích."],"nguoiTu":[{"ten":"Cao thủ trẻ tuổi Kim Giáp Vương tộc","tuChuong":"@c1327","tangDatToi":"Có thể thi triển","trangThai":"tu-vong"}],"tabs":{"tienTrinh":[{"chuong":"@c1327","loai":"thi triển","importance":"normal","giaiDoan":"Phòng thủ trước Thạch Hạo","text":"Cao thủ Kim Giáp tộc vận dụng tổ thuật, thu đầu và tứ chi vào giáp xác để vừa phòng thủ vừa công kích.","anchor":"nó vận dụng mạnh nhất tổ thuật, tứ chi còn có đầu lâu đều co vào màu vàng giáp xác bên trong"}]},"capNhatToi":"@c1327","nguon":["@c1327"]},{"id":"than-quang-vay-mi-tam","name":"Thần quang vảy mi tâm","cn":"","loai":"than-thong","loaiLabel":"Thiên phú thần thông","phamCap":"Không rõ","hePhai":"Vương tộc của nam tử có vảy ở mi tâm","soHuu":["Nam tử trẻ tuổi có vảy ở mi tâm"],"blurb":"Thần quang phát ra từ chiếc vảy ở mi tâm, vừa có khả năng dò xét cổ chủng vừa có thể hóa thành sát quang.","detail":"Nam tử trẻ tuổi mở chiếc vảy ở mi tâm và bắn ra ánh sáng sát thương, khiến lòng bàn tay Thạch Hạo chảy máu. Thần quang này trước đó còn được dùng để dò xét cổ chủng trong cơ thể các thiên tài Cửu Thiên Thập Địa.","thuocTinh":"Dò xét và sát phạt","congNang":["Dò xét cổ chủng trong cơ thể mục tiêu.","Phóng sát quang đủ sức làm lòng bàn tay Thạch Hạo chảy máu."],"nguoiTu":[{"ten":"Nam tử trẻ tuổi có vảy ở mi tâm","tuChuong":"@c1327","tangDatToi":"Có thể thi triển","trangThai":"tu-vong"}],"tabs":{"tienTrinh":[{"chuong":"@c1327","loai":"thi triển","importance":"normal","giaiDoan":"Đối đầu Thạch Hạo","text":"Nam tử trẻ tuổi mở vảy mi tâm và bắn sát quang làm lòng bàn tay Thạch Hạo bị thương.","anchor":"mi tâm của hắn nơi đó vảy mở ra, bắn ra một đạo đáng sợ giết chết ánh sáng"}]},"capNhatToi":"@c1327","nguon":["@c1327"]},{"id":"cuong-hoa-cua-thien-giac-nghi","name":"Cuồng hóa của Thiên Giác Nghĩ","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thiên phú","phamCap":"Không rõ","hePhai":"Thiên Giác Nghĩ","soHuu":["Thiên Giác Nghĩ"],"blurb":"Trạng thái cuồng hóa giúp Thiên Giác Nghĩ tăng vọt chiến lực, thậm chí có thể đạt gấp đôi bình thường.","detail":"Khi rơi vào trạng thái cuồng hóa, Thiên Giác Nghĩ tăng mạnh thực lực nhưng thần trí trở nên mơ hồ. Trạng thái này sớm tiêu hao tiềm năng sinh mệnh, khiến cơ thể kiệt sức và bị tổn thương sau chiến đấu.","thuocTinh":"Tăng cường chiến lực","yeuCau":"Thiên Giác Nghĩ rơi vào trạng thái cuồng nộ","uyLuc":"Có thể khiến thực lực tăng tới gấp đôi.","dacDiem":"Đổi lấy sức mạnh bằng tiềm năng sinh mệnh, sự tỉnh táo và tổn thương thân thể.","congNang":["Tăng mạnh thực lực của Thiên Giác Nghĩ, có thể đạt gấp đôi bình thường."],"nguoiTu":[{"ten":"Thiên Giác Nghĩ","tuChuong":"@c1328","tangDatToi":"","trangThai":"đang sử dụng"}],"trangThai":"Đang được sử dụng","capNhatToi":"@c1328","tabs":{"tienTrinh":[{"chuong":"@c1328","loai":"thi triển","importance":"normal","giaiDoan":"Cuồng hóa trên chiến trường","text":"Thiên Giác Nghĩ cuồng hóa vì nhận nhầm hậu duệ Hạc gia là Hạc Vô Song, khiến chiến lực tăng vọt nhưng thần trí trở nên mơ hồ.","anchor":"bởi vì sớm tiêu tốn sinh mệnh tiềm năng"}]},"nguon":["@c1328"]},{"id":"nang-luc-hoa-vat-chat-thanh-bach-ngan","name":"Năng lực hóa vật chất thành Bạch Ngân","cn":"","loai":"than-thong","loaiLabel":"Năng lực huyết mạch","phamCap":"Không rõ","hePhai":"Bạch Ngân Vương tộc","soHuu":["Ngân Linh"],"blurb":"Năng lực huyết mạch cho phép Ngân Linh biến vật chất và địa hình chung quanh thành Bạch Ngân để điều khiển.","detail":"Vật chất bị chuyển hóa thành chất lỏng màu trắng bạc, có thể ăn mòn chiến trường và bao vây đối thủ.","thuocTinh":"Bạch Ngân","congNang":["Hóa vật chất và địa hình thành Bạch Ngân để ăn mòn, thu về sử dụng và vây giết đối thủ."],"nguoiTu":[{"ten":"Ngân Linh","tuChuong":"@c1330","tangDatToi":"","trangThai":"đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c1330","loai":"thi triển","importance":"normal","giaiDoan":"Đối chiến Thạch Hạo","text":"Ngân Linh chuyển hóa vật chất chung quanh thành dòng Bạch Ngân để ăn mòn chiến trường và vây giết Thạch Hạo.","anchor":"hóa tất cả vật chất vì là Bạch Ngân, biến thành của mình, vây giết đối thủ"}]},"capNhatToi":"@c1330","nguon":["@c1330"]},{"id":"than-chu-hac-gia-dieu-dong-to-huyet","name":"Thần chú Hạc gia điều động tổ huyết","cn":"","loai":"bi-thuat","loaiLabel":"Bí thuật","phamCap":"Không rõ","hePhai":"Hạc gia","soHuu":["Hạc Tử Minh","Ngân Linh"],"blurb":"Thần chú của Hạc gia được sáng tạo để phối hợp với cổ tổ chân huyết.","detail":"Hạc Tử Minh truyền thần chú cho Ngân Linh, khiến chữ “Giết” do nửa giọt chân huyết tạo thành có thể bám theo và tự truy sát Thạch Hạo.","nguonGoc":"Hạc gia","yeuCau":"Phối hợp với cổ tổ chân huyết.","congNang":["Điều động chân huyết để dấu chữ “Giết” tự động truy sát mục tiêu."],"nguoiTu":[{"ten":"Hạc Tử Minh","tuChuong":"@c1330","tangDatToi":"","trangThai":"truyền thụ"},{"ten":"Ngân Linh","tuChuong":"@c1330","tangDatToi":"","trangThai":"đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c1330","loai":"thi triển","importance":"normal","giaiDoan":"Phối hợp tổ huyết","text":"Ngân Linh vận dụng thần chú do Hạc Tử Minh truyền để khiến chữ “Giết” bám theo Thạch Hạo như hình với bóng.","anchor":"quy tắc này thần chú chính là vì phối hợp hắn lòng bàn tay cái kia nửa giọt chân huyết mà sáng chế"}]},"capNhatToi":"@c1330","nguon":["@c1330"]},{"id":"chieu-hon-kinh","name":"Chiêu hồn kinh","cn":"","aliases":[],"loai":"bi-thuat","loaiLabel":"Kinh văn triệu hồn","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Các lão nhân Dị vực tại tế đàn"],"blurb":"Kinh văn được hàng trăm lão nhân Dị vực tụng niệm trong nghi lễ tại cổ chiến trường Đại Xích Thiên.","detail":"Chiêu hồn kinh tập hợp những mảnh tàn hồn và anh linh còn lưu lại trên chiến trường, qua đó dẫn phần tàn hồn của Lạc Ma trở về tế đàn.","thuocTinh":"Triệu hồn","congNang":["Triệu tập anh linh và tàn hồn còn lưu lại trong cổ chiến trường @c1333"],"nguoiTu":[{"ten":"Các lão nhân Dị vực tại tế đàn","tuChuong":"@c1333","tangDatToi":"Có thể chủ trì nghi lễ triệu hồn tập thể","trangThai":"đang sử dụng"}],"trangThai":"Đang được Dị vực sử dụng","capNhatToi":"@c1333","tabs":{"tienTrinh":[{"chuong":"@c1333","loai":"thi triển","importance":"normal","giaiDoan":"Triệu hồi tàn hồn Lạc Ma","text":"Hàng trăm lão nhân Dị vực tụng kinh để tập hợp anh linh và đưa tàn hồn Lạc Ma trở lại tế đàn.","anchor":"Bọn họ ở tụng chiêu hồn kinh"}]},"nguon":["@c1333"]},{"id":"than-chu-dieu-dong-tien-huyet","name":"Thần chú điều động Tiên huyết","cn":"","loai":"than-thong","loaiLabel":"Thần chú","phamCap":"Không rõ","hePhai":"Phượng Hoàng","soHuu":["Phượng Hoàng chưa thành niên"],"blurb":"Thần chú được Phượng Hoàng ngâm tụng để gọi dậy chiến ý còn lưu trong Tiên huyết.","detail":"Thần chú khiến Tiên huyết hóa thành các sinh linh mang một phần hình thái và uy thế lúc còn sống, sau đó tham chiến tại cửa cổ giới.","thuocTinh":"Điều động Tiên huyết","yeuCau":"Do Phượng Hoàng chưa thành niên thi triển","uyLuc":"Triệu hồi nhiều huyết linh công kích những kẻ tiến vào cổ giới.","dacDiem":"Đánh thức chiến ý vẫn tồn tại trong Tiên huyết sau một kỷ nguyên.","congNang":["Gọi dậy chiến ý trong Tiên huyết và khiến máu hóa hình chiến đấu."],"nguoiTu":[{"ten":"Phượng Hoàng chưa thành niên","tuChuong":"@c1336","tangDatToi":"Không rõ","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1336","loai":"thi triển","importance":"normal","giaiDoan":"Điều động huyết linh","text":"Phượng Hoàng ngâm thần chú, đánh thức chiến ý trong Tiên huyết và khiến máu hóa thành sinh linh chiến đấu.","anchor":"bắt đầu ngâm tụng một loại vô cùng thần chú thần bí"}]},"capNhatToi":"@c1336","nguon":["@c1336"]},{"id":"bat-tu-than-diem","name":"Bất tử Thần Diễm","cn":"","loai":"than-thong","loaiLabel":"Hỏa diễm thần thông","phamCap":"Không rõ","hePhai":"Bất tử chân phượng nhất mạch","soHuu":["Phượng Hoàng chưa thành niên"],"blurb":"Hỏa diễm thuộc bất tử chân phượng nhất mạch, được Phượng Hoàng chưa thành niên phun ra tại cửa cổ giới.","detail":"Ngọn lửa bao phủ khu vực biên giới cổ giới và mang sức hủy diệt sinh cơ.","thuocTinh":"Hỏa diễm","nguonGoc":"Bất tử chân phượng nhất mạch","uyLuc":"Có thể bao phủ chiến trường và hủy diệt sinh cơ.","congNang":["Bao phủ vùng cửa cổ giới và hủy diệt sinh cơ."],"nguoiTu":[{"ten":"Phượng Hoàng chưa thành niên","tuChuong":"@c1336","tangDatToi":"Không rõ","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1336","loai":"thi triển","importance":"normal","giaiDoan":"Phun Thần Diễm","text":"Phượng Hoàng phun Bất tử Thần Diễm để bao phủ vùng cửa cổ giới.","anchor":"phun ra chính là thuộc về bất tử chân phượng một mạch hỏa diễm"}]},"capNhatToi":"@c1336","nguon":["@c1336"]},{"id":"dao-am-cua-manh-thien-chinh","name":"Đạo âm của Mạnh Thiên Chính","cn":"","loai":"bi-thuat","loaiLabel":"Đạo thuật","phamCap":"Không rõ","hePhai":"Cửu Thiên Thập Địa","soHuu":["Mạnh Thiên Chính"],"blurb":"Đạo âm được Mạnh Thiên Chính đưa vào tiếng quát để đánh thức những người trẻ đang bị tiếng đàn mê hoặc.","detail":"Khi nhóm người trẻ chìm trong ảo giác do tiếng đàn gây ra, Mạnh Thiên Chính dùng tiếng quát mang đạo âm khiến họ chấn động và tỉnh lại.","thuocTinh":"Âm thanh, tỉnh thần","uyLuc":"Có thể phá ảnh hưởng mê hoặc tâm thần của tiếng đàn trong cổ giới.","dacDiem":"Được phát ra trực tiếp qua tiếng quát.","chieuTieuBieu":["Tiếng quát mang đạo âm"],"nguoiTu":[{"ten":"Mạnh Thiên Chính","tuChuong":"@c1339","tangDatToi":"","trangThai":"đang sử dụng"}],"congNang":["Đánh thức người đang bị mê hoặc tâm thần tại @c1339."],"trangThai":"đang lưu truyền","capNhatToi":"@c1339","tabs":{"tienTrinh":[{"chuong":"@c1339","loai":"thi triển","importance":"normal","giaiDoan":"Phá tiếng đàn mê hoặc","text":"Mạnh Thiên Chính dùng đạo âm trong tiếng quát để đánh thức nhóm người trẻ.","anchor":"\"Tỉnh lại!\" Đại trưởng lão Mạnh Thiên Chính gào to, dùng tới đạo âm."}]},"nguon":["@c1339"]},{"id":"tieng-dan-me-hoac-cua-phuong-ngo-tien-cam","name":"Tiếng đàn mê hoặc của Phượng ngô Tiên cầm","cn":"","loai":"than-thong","loaiLabel":"Âm luật đạo thuật","phamCap":"Không rõ","hePhai":"Bộ tộc Phượng Hoàng","soHuu":["Bộ xương trắng như tuyết đánh đàn"],"blurb":"Âm luật phát ra từ Phượng ngô Tiên cầm có thể gây ảo giác, công kích bằng âm phù và dẫn động các thi thể cường giả.","detail":"Tiếng đàn khiến người nghe tưởng bộ xương khôi phục huyết nhục thành một tuyệt đại tiên tử. Khi chuyển sang giao phong, đàn phát âm phù màu bạc và dây đàn hóa Giao Long; về sau âm điệu bi thương như chiêu hồn khiến các Tiên thi tiến đến.","thuocTinh":"Âm luật, mê hoặc, công kích, chiêu hồn","yeuCau":"Cần điều động Phượng ngô Tiên cầm","uyLuc":"Có thể đồng thời ảnh hưởng tâm thần, phát động công kích và dẫn động nhiều thi thể cường giả.","dacDiem":"Tác dụng thay đổi theo âm điệu và cách gảy đàn.","chieuTieuBieu":["Ảo giác tiên tử tái sinh","Âm phù màu bạc","Tiếng đàn chiêu hồn"],"nguoiTu":[{"ten":"Bộ xương trắng như tuyết đánh đàn","tuChuong":"@c1339","tangDatToi":"","trangThai":"đang thi triển"}],"congNang":["Khiến người nghe rơi vào ảo giác và gần như mất tỉnh táo tại @c1339.","Phát dây đàn cùng âm phù công kích mục tiêu tại @c1339.","Dẫn động thi thể Bất Hủ giả và thi thể trong mộ tiên tại @c1339."],"trangThai":"đang được thi triển","capNhatToi":"@c1339","tabs":{"tienTrinh":[{"chuong":"@c1339","loai":"thi triển","importance":"normal","giaiDoan":"Mê hoặc và chiêu hồn","text":"Bộ xương dùng tiếng đàn tạo ảo giác, phát động âm phù rồi dẫn các Tiên thi tới gần.","anchor":"Vẫn là bộ bạch cốt kia, là một vị huyết nhục biến mất tuyệt đại mỹ nhân, tiếng đàn rất yêu dị"}]},"nguon":["@c1339"]},{"id":"tien-dao-tan-tran-trong-co-gioi","name":"Tiên Đạo tàn trận trong cổ giới","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Tiên Đạo tàn trận","hePhai":"Không rõ","soHuu":[],"blurb":"Một đại trận tàn khuyết trong cổ giới có thể cuốn toàn bộ người hiện diện vào cảnh cổ chiến trường đầy di hài cường giả.","detail":"Trận pháp hiện lên khi cuộc giao phong làm quần thể kiến trúc rung chuyển. Nó che kín bầu trời, chuyển cảnh vật thành chiến trường cổ và buộc Dị vực cùng Mạnh Thiên Chính phải dùng Tiên khí phá đường thoát.","thuocTinh":"Không gian, vây nhốt","uyLuc":"Có thể đồng thời cuốn cả hai phe cùng nhiều pháp khí vào cảnh cổ chiến trường.","dacDiem":"Tuy đã tàn khuyết nhưng vẫn duy trì khả năng vây nhốt và chuyển đổi cảnh tượng.","congNang":["Vây nhốt toàn bộ người trong phạm vi tại @c1339.","Đưa người mắc trận vào cảnh cổ chiến trường đầy hài cốt tại @c1339."],"trangThai":"tàn khuyết","capNhatToi":"@c1339","tabs":{"tienTrinh":[{"chuong":"@c1339","loai":"xuất hiện","importance":"normal","giaiDoan":"Cuốn hai phe vào trận","text":"Tiên Đạo tàn trận hiện lên, che phủ toàn trường và cuốn tất cả vào cảnh cổ chiến trường.","anchor":"Một toà đại trận hiện lên, che kín bầu trời, đem tất cả mọi người đều cuốn vào"}]},"nguon":["@c1339"]},{"id":"co-dai-dai-tran-khoa-hu-khong","name":"Cổ đại đại trận khóa hư không","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Cổ đại trận","hePhai":"","soHuu":[],"blurb":"Một tòa cổ trận tồn tại qua vạn cổ, có phù văn khắc trên cả đất đai lẫn hư không quanh mộ tiên.","detail":"Khi thức tỉnh, đại trận khóa chặt hư không, gây nhiễu Luyện Tiên Hồ và Tiên Vương quấn vải liệm, qua đó cắt đứt con đường vượt không gian của cả Dị vực lẫn đoàn Cửu Thiên.","thuocTinh":"Không gian","uyLuc":"Có thể làm gián đoạn nỗ lực vượt hư không của hai vô thượng pháp khí.","dacDiem":"Phù văn và đồ án phức tạp vẫn tồn tại sau vạn cổ.","congNang":["Khóa hư không và ngăn các lực lượng trong mộ tiên mở đường đào thoát."],"trangThai":"Đã thức tỉnh","capNhatToi":"@c1340","tabs":{"tienTrinh":[{"chuong":"@c1340","loai":"xuất hiện","importance":"normal","giaiDoan":"Thức tỉnh","text":"Cổ đại trận thức tỉnh và cắt đứt đường vượt hư không của hai phe.","anchor":"một toà cổ đại đại trận ở đây thức tỉnh, gián đoạn bọn họ trốn con đường sống"}]},"nguon":["@c1340"]},{"id":"chien-tran-nam-khoi-loi","name":"Chiến trận năm khôi lỗi","cn":"","aliases":[],"loai":"khac","loaiLabel":"Chiến trận","phamCap":"Không rõ","hePhai":"Thiên Giác Nghĩ Tiên phủ","soHuu":["Thủ lĩnh năm chiến binh khôi lỗi","Bốn chiến binh khôi lỗi còn lại"],"blurb":"Chiến trận phối hợp của năm chiến binh khôi lỗi thuộc Thiên Giác Nghĩ Tiên phủ. Trận thế từng được dùng để chém giết nhiều cường giả dị vực.","detail":"Năm chiến binh phối hợp chiến mâu, thiên mâu và đại kích để vây công mục tiêu. Tại Thiên Thần Thư Viện, chiến trận phá nát bảo cụ hộ thân, xuyên thủng hai nguyên lão cùng những người Vương gia rồi tiêu diệt toàn bộ đoàn.","nguonGoc":"Chiến trường chống dị vực","uyLuc":"Có thể phá bảo cụ hộ thân và xuyên thủng các cao thủ Vương gia.","dacDiem":"Yêu cầu năm chiến binh khôi lỗi phối hợp binh khí theo trận thế.","congNang":["Phối hợp năm binh khí để phá bảo cụ và vây giết nhiều mục tiêu."],"nguoiTu":[{"ten":"Thủ lĩnh năm chiến binh khôi lỗi","tuChuong":"@c1344","tangDatToi":"Có thể cùng bốn chiến binh triển khai hoàn chỉnh","trangThai":"đang sử dụng"},{"ten":"Bốn chiến binh khôi lỗi còn lại","tuChuong":"@c1344","tangDatToi":"Có thể phối hợp cùng thủ lĩnh","trangThai":"đang sử dụng"}],"trangThai":"Còn được sử dụng","capNhatToi":"@c1344","tabs":{"tienTrinh":[{"chuong":"@c1344","loai":"thi triển","importance":"normal","giaiDoan":"Triển khai hoàn chỉnh","text":"Năm chiến binh khôi lỗi triển khai chiến trận, phá bảo cụ hộ thân và tiêu diệt đoàn người Vương gia.","anchor":"Đây là chiến trận, đã từng ở trên chiến trường, chém giết vô số dị vực cường giả"}]},"nguon":["@c1344"]},{"id":"tien-dao-phu-van-tren-chien-mau-den","name":"Tiên Đạo phù văn trên chiến mâu đen","cn":"","aliases":[],"loai":"bi-thuat","loaiLabel":"Phù văn","phamCap":"Tiên Đạo","hePhai":"Thiên Giác Nghĩ Tiên phủ","soHuu":["Thủ lĩnh năm chiến binh khôi lỗi"],"blurb":"Tiên Đạo phù văn khắc trên chiến mâu đen của thủ lĩnh khôi lỗi. Khi kích phát, phù văn hóa thành lửa đen thiêu thân thể và nguyên thần.","detail":"Lửa đen do phù văn tạo ra vừa thiêu đốt thân thể, vừa giam nguyên thần trong xác để ngăn đối phương thoát ra. Sức mạnh này từng được dùng trên chiến trường để giết nhiều quân dị vực và đã thiêu Vương Thiên Minh thành than, đốt nguyên thần thành bụi.","thuocTinh":"Tiên Đạo, lửa đen","nguonGoc":"Tiên Đạo phù văn từng được dùng trên chiến trường chống dị vực","uyLuc":"Thiêu thân thể thành than và đốt nguyên thần thành bụi.","dacDiem":"Có thể giam nguyên thần trong thân thể trong lúc lửa đen ăn mòn mục tiêu.","congNang":["Tạo lửa đen thiêu đốt thân thể.","Giam giữ và ăn mòn nguyên thần, ngăn mục tiêu thoát xác."],"nguoiTu":[{"ten":"Thủ lĩnh năm chiến binh khôi lỗi","tuChuong":"@c1344","tangDatToi":"Có thể kích phát phù văn trên chiến mâu","trangThai":"đang sử dụng"}],"trangThai":"Còn được sử dụng","capNhatToi":"@c1344","tabs":{"tienTrinh":[{"chuong":"@c1344","loai":"thi triển","importance":"normal","giaiDoan":"Kích phát lửa đen","text":"Thủ lĩnh chiến binh khôi lỗi kích phát Tiên Đạo phù văn trên chiến mâu để thiêu diệt Vương Thiên Minh.","anchor":"đây là Tiên Đạo phù văn, năm đó, nó từng giết địch, ở trên chiến trường giết dị vực vô số người"}]},"nguon":["@c1344"]},{"id":"dai-tran-phong-ho-ha-vien-vuong-gia","name":"Đại trận phòng hộ hạ viện Vương gia","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Vương gia","soHuu":["Hạ viện Vương gia gần Thiên Thần Thư Viện"],"blurb":"Trận pháp phòng hộ của hạ viện Vương gia, được kích hoạt khẩn cấp khi chiến thuyền của đoàn Thạch Hạo xông tới.","detail":"Đại trận tạo thành liên miên phù văn để ngăn kẻ địch xâm nhập nhưng không chặn nổi chiến thuyền, khiến trận đài và cửa pháo đài nhanh chóng bị phá xuyên.","congNang":["Tạo phù văn phòng hộ nhằm ngăn kẻ địch xâm nhập hạ viện tại @c1345."],"uyLuc":"Không chống nổi chiến thuyền của đoàn Thạch Hạo tại @c1345.","nguonGoc":"Trận pháp bố trí tại hạ viện Vương gia gần Thiên Thần Thư Viện.","trangThai":"Bị phá","capNhatToi":"@c1345","tabs":{"tienTrinh":[{"chuong":"@c1345","loai":"thi triển","importance":"normal","giaiDoan":"Bị phá xuyên","text":"Người trong hạ viện khẩn cấp mở đại trận và triển khai phù văn, nhưng chiến thuyền vẫn phá xuyên phòng tuyến.","anchor":"cấp tốc mở ra đại trận, lấy ra liên miên phù văn các loại"}]},"nguon":["@c1345"]},{"id":"vuong-gia-chien-tran","name":"Vương gia chiến trận","cn":"","aliases":["Tuyệt thế chiến trận của Vương gia","Cổ lão sát trận Vương gia"],"loai":"khac","loaiLabel":"Chiến trận","phamCap":"Không rõ","hePhai":"Vương gia","soHuu":["Vương gia"],"blurb":"Chiến trận do mấy nghìn tinh nhuệ Vương gia cùng triển khai, tạo cương phong và chiến khí bao phủ trời đất. Trận thế không thể ngăn cản năm binh sĩ con rối.","detail":"Vương gia chiến trận hợp nhất sức mạnh của mấy nghìn nhân mã, khiến cương phong cuồn cuộn và chiến khí phủ kín khu vực giao tranh. Uy thế của trận pháp đủ làm người thuộc các Trường Sinh thế gia khác kinh hãi, nhưng đội hình vẫn bị năm binh sĩ mặc giáp đen trực diện quét ngang.","thuocTinh":"Hợp nhất chiến khí của đông đảo quân sĩ","uyLuc":"Chiến khí và cương phong bao phủ trời đất, có thể kinh động cả đại vực.","dacDiem":"Cần mấy nghìn nhân mã đồng thời sắp xếp thành trận.","congNang":["Hợp nhất chiến khí của mấy nghìn tinh nhuệ Vương gia thành một trận thế quy mô lớn."],"nguoiTu":[{"ten":"Đội quân vương bài Vương gia","tuChuong":"@c1346","tangDatToi":"Có thể triển khai trận thế hoàn chỉnh bằng mấy nghìn nhân mã","trangThai":"Đội hình bị năm binh sĩ con rối quét ngang"}],"trangThai":"Bị phá","capNhatToi":"@c1346","tabs":{"tienTrinh":[{"chuong":"@c1346","loai":"thi triển","importance":"normal","giaiDoan":"Triển khai tại Thiên Thần Thư Viện","text":"Mấy nghìn tinh nhuệ Vương gia triển khai chiến trận tạo cương phong và chiến khí bao phủ trời đất, nhưng trận thế bị năm binh sĩ con rối quét ngang.","anchor":"mấy ngàn nhân mã sắp xếp, cương phong cuồn cuộn, bao phủ trên trời dưới đất"}]},"nguon":["@c1346"]},{"id":"phu-van-thu-ho-cua-thien-giac-nghi","name":"Phù văn thủ hộ của Thiên Giác Nghĩ","cn":"","loai":"than-thong","loaiLabel":"Tiên Đạo phù văn","phamCap":"","hePhai":"Thiên Giác Nghĩ","soHuu":["Năm binh sĩ con rối của Thiên Giác Nghĩ"],"blurb":"Phù văn do Thiên Giác Nghĩ chúc phúc, lưu lại trên thân những lão binh dưới quyền.","detail":"Khi Vương Chân dùng mảnh Tiên Đạo pháp chỉ công kích, phù văn thủ hộ phát sáng trên thân lão binh và trực tiếp nghiền nát mảnh pháp chỉ không trọn vẹn.","thuocTinh":"Bảo hộ","nguonGoc":"Do Thiên Giác Nghĩ ban phúc","congNang":["Bảo hộ lão binh và nghiền nát mảnh Tiên Đạo pháp chỉ không trọn vẹn."],"nguoiTu":[{"ten":"Năm binh sĩ con rối của Thiên Giác Nghĩ","tuChuong":"@c1347","tangDatToi":"","trangThai":"được chúc phúc"}],"tabs":{"tienTrinh":[{"chuong":"@c1347","loai":"thi triển","importance":"normal","giaiDoan":"Kích hoạt bảo hộ","text":"Phù văn phát sáng trên thân lão binh và nghiền nát mảnh Tiên Đạo pháp chỉ của Vương Chân.","anchor":"lão binh trên người sáng lên một mảnh Phù Văn, trực tiếp đem góc kia pháp chỉ nát bấy"}]},"capNhatToi":"@c1347","nguon":["@c1347"]},{"id":"phap-tuong-cua-vuong-nhi","name":"Pháp tướng của Vương Nhị","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"Vương gia","soHuu":["Vương Nhị"],"blurb":"Thần thông giúp Vương Nhị hiển hóa một bóng người khổng lồ đỉnh thiên lập địa.","detail":"Khi được triển khai trên đầu chiến thuyền, Pháp tướng cao không biết bao nhiêu vạn trượng và tỏa ra khí thế khủng bố.","thuocTinh":"Hiển hóa Pháp tướng khổng lồ","uyLuc":"Tạo ra thân ảnh cao hàng vạn trượng cùng khí thế khủng bố.","dacDiem":"Pháp tướng đứng sừng sững giữa trời, mang hình thái đỉnh thiên lập địa.","congNang":["Hiển hóa thân ảnh khổng lồ cao không biết bao nhiêu vạn trượng tại @c1348."],"nguoiTu":[{"ten":"Vương Nhị","tuChuong":"@c1348","tangDatToi":"Chưa rõ","trangThai":"đang tu luyện"}],"trangThai":"đang lưu truyền","capNhatToi":"@c1348","tabs":{"tienTrinh":[{"chuong":"@c1348","loai":"thi triển","importance":"normal","giaiDoan":"Hiển hóa Pháp tướng","text":"Vương Nhị triển khai Pháp tướng khổng lồ trên đầu chiến thuyền khi uy hiếp Thiên Thần Thư Viện.","anchor":"Đây là hắn Pháp tướng, đỉnh thiên lập địa, cao cũng không biết bao nhiêu vạn trượng"}]},"nguon":["@c1348"]},{"id":"tien-dao-tan-tran-thien-than-thu-vien","name":"Tiên Đạo tàn trận Thiên Thần Thư Viện","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Tiên Đạo tàn trận","hePhai":"Thiên Thần Thư Viện","soHuu":["Thiên Thần Thư Viện"],"blurb":"Tiên Đạo tàn trận là một góc không trọn vẹn của Tiên Đạo trận pháp, được chôn dưới Thiên Thần Thư Viện. Khi được kích hoạt, tàn trận ngưng tụ nhiều tầng phòng hộ để chống Trường Sinh chiến kích và có thể đẩy ngược chiến kích sau khi các tầng phòng hộ bị xuyên phá.","detail":"Được chôn dưới Thiên Thần Thư Viện, tàn trận này chỉ còn lại một góc của Tiên Đạo trận pháp hoàn chỉnh. Khi Trường Sinh chiến kích tấn công, nó lần lượt dựng màn sáng như tinh hà và ngưng tụ thuẫn bài để bảo vệ thư viện; cả hai tầng phòng hộ sau đó đều bị phá, khiến năng lượng tích lũy của tàn trận bị tiêu hao nghiêm trọng. Dù vậy, tàn trận vẫn có thể đẩy ngược Trường Sinh chiến kích sau khi các lớp phòng hộ bị xuyên phá. @c1349","thuocTinh":"Phòng hộ","nguonGoc":"Được chôn dưới Thiên Thần Thư Viện","uyLuc":"Có thể đẩy ngược Trường Sinh chiến kích sau khi các tầng phòng hộ bị xuyên phá.","dacDiem":"Chỉ còn một góc không trọn vẹn của Tiên Đạo trận pháp.","congNang":["Ngưng tụ nhiều tầng phòng hộ, gồm màn sáng như tinh hà và thuẫn bài, để bảo vệ Thiên Thần Thư Viện. @c1349","Đẩy ngược Trường Sinh chiến kích sau khi các tầng phòng hộ bị xuyên phá. @c1349"],"trangThai":"Tổn hại nặng và tiêu hao phần lớn năng lượng","capNhatToi":"@c1349","tabs":{"tienTrinh":[{"chuong":"@c1349","loai":"xuất hiện","importance":"major","giaiDoan":"Kích hoạt phòng hộ","text":"Tiên Đạo tàn trận được kích hoạt để chống Trường Sinh chiến kích nhưng các tầng phòng hộ lần lượt bị phá.","anchor":"Nơi đây, có chôn cổ trận, mặc dù là không trọn vẹn, nhưng cũng là Tiên Đạo trận pháp một góc"}]},"nguon":["@c1349"]},{"id":"vuot-gioi-duong-noi","name":"Vượt giới đường nối","cn":"","loai":"than-thong","loaiLabel":"Thần thông không gian","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":[],"blurb":"Đại pháp lực mở thông Càn Khôn và trải một con đường ánh sáng giữa các tầng trời.","detail":"Thần thông tạo kim quang đại đạo để cổ chiến xa Kim gia đi từ Thanh Vi Thiên tới Vô Lượng Thiên, vượt qua khoảng cách giữa các tầng trời.","thuocTinh":"Không gian","uyLuc":"Có thể mở thông Càn Khôn giữa các tầng trời.","congNang":["Mở đường vượt qua các tầng trời @c1352"],"dacDiem":"Biểu hiện thành kim quang đại đạo nối liền hai tầng trời.","trangThai":"đang lưu truyền","capNhatToi":"@c1352","tabs":{"tienTrinh":[{"chuong":"@c1352","loai":"thi triển","importance":"normal","giaiDoan":"Mở đường vượt giới","text":"Một cường giả dùng đại pháp lực mở thông Càn Khôn, tạo kim quang đại đạo để cổ chiến xa Kim gia vượt từ Thanh Vi Thiên tới Vô Lượng Thiên.","anchor":"Có người lấy vô thượng đại pháp lực tạo ra Càn Khôn, từ trên chín tầng trời khác một chỗ đến"}]},"nguon":["@c1352"]},{"id":"chin-dao-cam-che-nguyen-than-thach-hao","name":"Chín đạo cấm chế trong Nguyên Thần Thạch Hạo","cn":"","aliases":[],"loai":"bi-thuat","loaiLabel":"Cấm chế","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Mạnh Thiên Chính"],"blurb":"Chín đạo cấm chế do Mạnh Thiên Chính bố trí trong Nguyên Thần Thạch Hạo để bảo vệ một phần kinh văn.","detail":"Cấm chế ngăn người ngoài xem phần kinh văn trong Nguyên Thần Thạch Hạo. Nếu có người cưỡng ép xem duyệt, kinh văn sẽ tự ma diệt.","thuocTinh":"Nguyên Thần cấm chế","nguonGoc":"Do Mạnh Thiên Chính bố trí trong Nguyên Thần Thạch Hạo.","yeuCau":"Không rõ","uyLuc":"Có thể ngăn ngoại nhân xem duyệt và khiến kinh văn tự ma diệt nếu bị cưỡng ép.","dacDiem":"Gồm chín đạo cấm chế cùng bảo vệ phần kinh văn.","trangThai":"Đang bảo vệ kinh văn","capNhatToi":"@c1353","congNang":["Bảo vệ kinh văn trong Nguyên Thần Thạch Hạo và ngăn ngoại nhân xem duyệt."],"nguoiTu":[{"ten":"Mạnh Thiên Chính","tuChuong":"@c1353","tangDatToi":"Người bố trí","trangThai":"Đã bố trí cấm chế"}],"tabs":{"tienTrinh":[{"chuong":"@c1353","loai":"xuất hiện","importance":"normal","giaiDoan":"Bảo vệ kinh văn","text":"Mạnh Thiên Chính tiết lộ đã bố trí chín đạo cấm chế trong Nguyên Thần Thạch Hạo để ngăn người ngoài xem phần kinh văn.","anchor":"ngoại nhân không cách nào xem duyệt kinh văn, bằng không này kinh sẽ bị ma diệt"}]},"nguon":["@c1353"]},{"id":"kinh-van-thach-hao-nhan-duoc","name":"Kinh văn Thạch Hạo nhận được","cn":"","aliases":[],"loai":"cong-phap","loaiLabel":"Kinh văn","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Thạch Hạo"],"blurb":"Một phần kinh văn phi thường do Thạch Hạo nhận được và từng đưa Mạnh Thiên Chính tìm hiểu.","detail":"Kinh văn được giữ trong Nguyên Thần Thạch Hạo và bảo vệ bằng chín đạo cấm chế. Mạnh Thiên Chính chỉ đồng ý cho Vương gia xem nếu thế lực này lập đại công cho Cửu Thiên Thập Địa.","thuocTinh":"Kinh văn chưa rõ tên","nguonGoc":"Do Thạch Hạo nhận được trước khi đưa Mạnh Thiên Chính tìm hiểu.","yeuCau":"Muốn xem phải vượt qua điều kiện và sự bảo vệ do Mạnh Thiên Chính đặt ra.","dacDiem":"Được đánh giá phi thường bất phàm và được bảo vệ trong Nguyên Thần Thạch Hạo.","trangThai":"Được bảo vệ trong Nguyên Thần Thạch Hạo","capNhatToi":"@c1353","congNang":[],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1353","tangDatToi":"Người nắm giữ","trangThai":"Đang giữ trong Nguyên Thần"},{"ten":"Mạnh Thiên Chính","tuChuong":"@c1353","tangDatToi":"Đã tìm hiểu","trangThai":"Đã xem xét kinh văn"}],"tabs":{"tienTrinh":[{"chuong":"@c1353","loai":"xuất hiện","importance":"normal","giaiDoan":"Được nêu làm điều kiện","text":"Mạnh Thiên Chính tiết lộ Thạch Hạo từng đưa ông tìm hiểu phần kinh văn này và lấy quyền xem kinh làm điều kiện đối với Vương gia.","anchor":"Hoang đứa bé này chiếm được một phần kinh văn, hắn đưa ta tìm hiểu"}]},"nguon":["@c1353"]},{"id":"to-thuat-mien-dich-van-phap","name":"Tổ thuật miễn dịch vạn pháp","cn":"","loai":"than-thong","loaiLabel":"Tổ thuật","phamCap":"Tổ thuật Vô Địch","hePhai":"Đế Tộc cổ lão nhất dị vực","soHuu":[],"blurb":"Tổ thuật hình thành từ thiên phú đặc hữu của một Đế Tộc cực kỳ cổ xưa ở dị vực, có khả năng làm các loại thần thông, bảo thuật và pháp lực mất hiệu lực.","detail":"Đế Tộc sở hữu thuật này còn cổ xưa hơn hai tộc An Lan và Du Đà. Qua một đến hai kỷ nguyên nghiên cứu, năng lực miễn dịch pháp lực đã phát triển thành tổ thuật thâm thúy với đặc tính vạn pháp đều diệt.","thuocTinh":"Miễn dịch pháp lực","nguonGoc":"Đế Tộc cổ lão nhất dị vực","uyLuc":"Có thể miễn dịch các loại thần thông, bảo thuật và pháp lực.","dacDiem":"Được hoàn thiện qua thời gian nghiên cứu kéo dài một đến hai kỷ nguyên.","congNang":["Miễn dịch các loại thần thông, bảo thuật và pháp lực."],"chieuTieuBieu":[],"cacTang":[],"trangThai":"Đang được Đế Tộc dị vực truyền thừa","capNhatToi":"@c1354","tabs":{"tienTrinh":[{"chuong":"@c1354","loai":"xuất hiện","importance":"normal","giaiDoan":"Hé lộ tổ thuật","text":"Các lão giả hé lộ một Đế Tộc cổ xưa sở hữu tổ thuật có thể miễn dịch thần thông, bảo thuật và khiến vạn pháp đều diệt.","anchor":"có một loại thiên phú, hình thành chân chính Vô Địch với thế gian tổ thuật, có thể miễn dịch các loại thần thông, bảo thuật, vạn pháp đều diệt"}]},"nguon":["@c1354"]},{"id":"tien-kinh","name":"Tiên kinh","cn":"","loai":"cong-phap","loaiLabel":"Tiên Đạo kinh văn","phamCap":"Vô thượng kinh văn Tiên Đạo","hePhai":"Cổ pháp Tiên Đạo","soHuu":["Thạch Hạo"],"blurb":"Tiên kinh là truyền thừa Tiên Đạo hoàn chỉnh do tuyệt đại cao thủ thời Tiên cổ lưu lại cho hậu nhân, dành cho sinh linh có nền móng cổ pháp và đã tu ra tiên khí. Kinh văn lấy chữ “chủng” làm cốt lõi, giúp Thạch Hạo hoàn thiện căn cơ còn thiếu của ba đạo tiên khí và thúc đẩy thân thể biến hóa gần như thoát thai hoán cốt.","detail":"Sau khi đạt Hư Đạo cảnh, Thạch Hạo tự mở Tiên kinh và lĩnh hội nền tảng “chủng” của hệ thống cổ pháp @c1357. Kinh văn trình bày đạo chủng, mồi lửa, Ma chủng và tiên chủng đều quy về chữ “chủng”; đồng thời điều chỉnh ba đạo tiên khí mà Thạch Hạo từng cưỡng ép ngưng tụ nhưng chưa có gốc rễ. Khi vận chuyển kinh văn, ba đạo tiên khí tuần hoàn trong cơ thể, khiến xương cốt cộng hưởng Tiên âm và từng tấc thân thể được gột rửa, biến đổi.","thuocTinh":"Tiên Đạo, cổ pháp","nguonGoc":"Do tuyệt đại cao thủ Tiên cổ lưu lại làm truyền thừa cho hậu nhân.","yeuCau":"Người xem phải đạt Hư Đạo cảnh để tự mở kinh, có nền móng Tiên cổ và đã tu ra tiên khí.","uyLuc":"Khi được vận chuyển, Tiên kinh có thể dẫn động ba đạo tiên khí tuần hoàn, khiến xương cốt cộng hưởng Tiên âm và thân thể biến đổi từng tấc.","dacDiem":"Lấy toàn cảnh nền tảng “chủng” của cổ pháp làm cốt lõi, đồng thời có khả năng điều chỉnh tiên khí đã hình thành nhưng còn thiếu gốc rễ.","chieuTieuBieu":["Phạt mao tẩy tủy","Hoàn thiện căn cơ cổ pháp"],"cacTang":[{"ten":"Nhập môn","moTa":"Người tu dựa vào sức mạnh bản thân mở được kinh thư và bắt đầu lĩnh hội kinh văn.","chuong":"@c1357"}],"trangThai":"Đang được Thạch Hạo tham ngộ","capNhatToi":"@c1357","congNang":["Giải thích nền tảng “chủng” của hệ thống cổ pháp, bao quát đạo chủng, mồi lửa, Ma chủng và tiên chủng @c1357.","Bù đắp gốc rễ còn thiếu của ba đạo tiên khí do Thạch Hạo cưỡng ép ngưng tụ.","Dẫn động ba đạo tiên khí tuần hoàn trong cơ thể và khiến xương cốt cộng hưởng Tiên âm.","Gột rửa thân thể, thúc đẩy quá trình biến hóa gần như thoát thai hoán cốt."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1357","tangDatToi":"Nhập môn","trangThai":"Đang tu luyện"}],"dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1357","loai":"xuất hiện","importance":"major","giaiDoan":"Mở kinh và nhập môn","text":"Thạch Hạo tự mở kinh thư sau khi đạt Hư Đạo cảnh, lĩnh hội nền tảng “chủng” của cổ pháp và bắt đầu được kinh văn gột rửa thân thể.","anchor":"Mà bộ kinh văn này chính là vì tu ra tiên khí giả chuẩn bị"}]},"nguon":["@c1357"]},{"id":"tran-toc-co-kinh-kim-gia","name":"Trấn tộc cổ kinh Kim gia","cn":"","loai":"luyen-the","loaiLabel":"Cổ kinh luyện thể","phamCap":"Trấn tộc cổ kinh","hePhai":"Kim gia","soHuu":["Kim gia"],"blurb":"Truyền thừa cổ xưa của Kim gia, chú trọng rèn đúc thân thể và tu hành gân cốt. Một phần kinh thư lưu truyền được cho là từng ảnh hưởng đến hệ thống pháp đương đại.","detail":"Cổ kinh có nguồn gốc từ kỷ nguyên trước và là truyền thừa trọng yếu của Kim gia. Nội dung được biết đến nhấn mạnh việc rèn luyện thân thể cùng gân cốt, có tính bao dung gần với pháp đương đại. Thạch Hạo chỉ đích danh bộ kinh này khi Kim Triển đề nghị trao đổi cổ kinh gia tộc lấy Tiên kinh.","thuocTinh":"Luyện thể, gân cốt","nguonGoc":"Truyền thừa Kim gia từ kỷ nguyên trước.","yeuCau":"Không rõ","uyLuc":"Có khả năng rèn đúc thân thể và tu hành gân cốt.","dacDiem":"Mang tính bao dung gần với pháp đương đại và được đồn đã ảnh hưởng đến sự hình thành hệ thống cốt văn.","trangThai":"Được Kim gia nắm giữ","capNhatToi":"@c1357","congNang":["Rèn luyện thân thể và gân cốt."],"nguoiTu":[],"dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1357","loai":"xuất hiện","importance":"normal","giaiDoan":"Được đề nghị trao đổi","text":"Thạch Hạo yêu cầu Kim gia dùng trấn tộc cổ kinh chuyên rèn luyện thân thể và gân cốt để đổi lấy Tiên kinh.","anchor":"bọn họ kinh văn cường điệu với thân thể rèn đúc, gân cốt tu hành, có chút khác loại"}]},"nguon":["@c1357"]},{"id":"tien-kinh-lay-chung-lam-coi-nguon","name":"Tiên kinh lấy “Chủng” làm cội nguồn","cn":"","loai":"cong-phap","loaiLabel":"Cổ kinh Tiên cổ","phamCap":"Tiên kinh","hePhai":"Tiên cổ pháp","soHuu":["Thạch Hạo"],"blurb":"Tiên kinh lấy “Chủng” phát triển trong thân thể làm cội nguồn, thuộc hệ thống Tiên cổ pháp và khác với kiếp này pháp. Công pháp có thể phân giải tiên khí thành hi quang, gieo vào khắp máu thịt để tiếp tục thai nghén, đồng thời chỉnh sửa và đánh bóng đạo cốt. Kết quả tu luyện thay đổi tùy theo căn cơ và “Chủng” của mỗi người.","detail":"Khi Thạch Hạo vận chuyển Tiên kinh, ba đạo tiên khí trong cơ thể phân giải thành hi quang rồi cắm rễ trong từng tấc máu thịt, từ đó tiếp tục được nuôi dưỡng và thai nghén. Ngay trong lần ôn dưỡng đầu tiên, thân thể hắn đã phát sinh cộng hưởng, cắt bỏ phần xương không phù hợp và tiến hành chỉnh sửa, đánh bóng đạo cốt. Đây là Tiên cổ pháp lấy “Chủng” làm nền tảng; thành quả đạt được không cố định mà phụ thuộc vào căn cơ và “Chủng” của từng người. @c1358","thuocTinh":"Lấy thân thể làm thổ nhưỡng nuôi dưỡng tiên khí","nguonGoc":"Tiên cổ pháp","yeuCau":"Dùng “Chủng” phát triển trong thân thể","uyLuc":"Lần ôn dưỡng đầu tiên đã khiến toàn thân Thạch Hạo cộng hưởng, cắt bỏ phần xương không phù hợp và thúc đẩy quá trình chỉnh sửa đạo cốt. @c1358","dacDiem":"Tiên cổ pháp lấy “Chủng” phát triển trong thân thể làm cội nguồn; kết quả tu luyện của mỗi người có thể khác nhau tùy căn cơ và “Chủng”.","chieuTieuBieu":["Phân giải tiên khí thành hi quang","Ôn dưỡng và chỉnh sửa đạo cốt"],"trangThai":"Được Thạch Hạo lĩnh hội và chia sẻ","capNhatToi":"@c1358","congNang":["Phân giải tiên khí thành hi quang và khiến chúng cắm rễ khắp máu thịt. @c1358","Nuôi dưỡng, tái thai nghén tiên khí trong từng tấc máu thịt. @c1358","Khiến thân thể cộng hưởng, cắt bỏ những phần xương không phù hợp. @c1358","Chỉnh sửa và đánh bóng đạo cốt. @c1358"],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1358","tangDatToi":"Bước đầu lĩnh hội","trangThai":"đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c1358","loai":"xuất hiện","importance":"major","giaiDoan":"Bước đầu lĩnh hội","text":"Thạch Hạo vận chuyển Tiên kinh, khiến ba đạo tiên khí phân giải thành hi quang và cắm rễ khắp máu thịt. Kinh văn đồng thời cưỡng ép chỉnh sửa đạo cốt của hắn.","anchor":"Ba đạo tiên khí hóa thành hi quang sau, giấu ở mỗi một tấc máu thịt bên trong"}]},"nguon":["@c1358"]},{"id":"tien-phu-va-tran-phap-de-thanh","name":"Tiên phù và trận pháp Đế Thành","cn":"","aliases":[],"loai":"khac","loaiLabel":"Trận pháp phòng thủ","phamCap":"","hePhai":"Đế quan","soHuu":[],"blurb":"Hệ thống tiên phù và trận pháp phòng thủ bao phủ Đế Thành, phối hợp với vị trí đầu mối không gian để trấn áp Biên Hoang.","detail":"Tiên phù vô thượng cùng trận pháp dày đặc trải liên miên trên cự thành. Hệ thống này giúp Đế Thành giữ đầu mối không gian trọng yếu và ngăn quân dị vực tiến sâu vào Cửu Thiên Thập Địa.","thuocTinh":"Phòng thủ và trấn áp không gian","uyLuc":"Có thể phối hợp với Đế Thành để ngăn dị vực tiến quân thần tốc qua đầu mối không gian.","dacDiem":"Gồm tiên phù vô thượng và trận pháp dày đặc bao phủ cự thành.","congNang":["Trấn áp đầu mối không gian trọng yếu tại Biên Hoang.","Tăng cường khả năng phòng thủ của Đế Thành trước dị vực."],"trangThai":"Đang vận hành","capNhatToi":"@c1360","tabs":{"tienTrinh":[{"chuong":"@c1360","loai":"xuất hiện","importance":"normal","giaiDoan":"Bao phủ Đế Thành","text":"Tiên phù và trận pháp hiện diện dày đặc trên Đế Thành, góp phần trấn áp đầu mối không gian và chặn bước tiến của dị vực.","anchor":"đồng thời khắc có vô thượng Tiên phù hiệu, trận pháp liên miên, dày đặc vô biên"}]},"nguon":["@c1360"]},{"id":"tien-dao-cua-dai-than-tien-thu-de-quan","name":"Tiễn đạo của đại thần tiễn thủ Đế quan","cn":"","aliases":[],"loai":"khac","loaiLabel":"Tiễn thuật","phamCap":"","hePhai":"Đế quan","soHuu":["Đại thần tiễn thủ tóc tai bù xù"],"blurb":"Tiễn thuật của một trong mười đại thần tiễn thủ Đế quan, có khả năng công kích mục tiêu ở tinh vực xa xôi.","detail":"Người tu luyện liên tục bắn tên về vực ngoại. Theo lời người dẫn đường, mỗi mũi tên của vị thần tiễn thủ này có thể bắn nát một ngôi sao tại tinh vực khác.","thuocTinh":"Tiễn thuật công kích tầm cực xa","uyLuc":"Một mũi tên có thể bắn nát một ngôi sao ở tinh vực khác.","dacDiem":"Có thể nhắm bắn mục tiêu vượt qua khoảng cách giữa các tinh vực.","congNang":["Công kích mục tiêu tại tinh vực xa xôi.","Bắn nát một ngôi sao bằng một mũi tên."],"nguoiTu":[{"ten":"Đại thần tiễn thủ tóc tai bù xù","tuChuong":"@c1360","tangDatToi":"Một trong mười đại thần tiễn thủ Đế quan","trangThai":"Đang tu luyện và sử dụng"}],"trangThai":"Đang được sử dụng","capNhatToi":"@c1360","tabs":{"tienTrinh":[{"chuong":"@c1360","loai":"thi triển","importance":"normal","giaiDoan":"Bắn về vực ngoại","text":"Một đại thần tiễn thủ Đế quan liên tục luyện bắn về vực ngoại, thể hiện năng lực công kích những ngôi sao ở tinh vực khác.","anchor":"dù cho lại xa, cũng là một mũi tên bắn nát một viên"}]},"nguon":["@c1360"]},{"id":"phap-luc-got-rua-cua-to-dan","name":"Pháp lực gột rửa của tổ đàn","cn":"","loai":"than-thong","loaiLabel":"Pháp lực gia trì","phamCap":"Không rõ","hePhai":"Tổ đàn","soHuu":[],"blurb":"Pháp lực do đại đạo phù văn tại tổ đàn dẫn xuống, đem lại cơ duyên cho người được tiếp dẫn.","detail":"Đại đạo phù văn bao phủ nhóm Thạch Hạo và Tào Vũ Sinh, khiến đạo cốt của họ cộng hưởng và ánh sáng tuần hoàn ra vào thân thể.","thuocTinh":"Đạo tắc và pháp lực","uyLuc":"Có thể gột rửa thân thể và khiến đạo cốt cộng hưởng.","dacDiem":"Được ban xuống khi kim quang đại đạo tiếp dẫn người vào sâu trong tổ đàn.","congNang":["Gột rửa thân thể và khiến đạo cốt cộng hưởng tại tổ đàn."],"chieuTieuBieu":[],"cacTang":[],"trangThai":"Đang tồn tại tại tổ đàn","capNhatToi":"@c1363","nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1363","tangDatToi":"Nhận gột rửa","trangThai":"Đã tiếp nhận"},{"ten":"Thạch Nghị","tuChuong":"@c1363","tangDatToi":"Nhận gột rửa","trangThai":"Đã tiếp nhận"},{"ten":"Tần Hạo","tuChuong":"@c1363","tangDatToi":"Nhận gột rửa","trangThai":"Đã tiếp nhận"},{"ten":"Tào Vũ Sinh","tuChuong":"@c1363","tangDatToi":"Nhận gột rửa","trangThai":"Đã tiếp nhận"}],"tabs":{"tienTrinh":[{"chuong":"@c1363","loai":"thi triển","importance":"normal","giaiDoan":"Gia trì người được tiếp dẫn","text":"Đại đạo phù văn gột rửa nhóm Thạch Hạo và khiến đạo cốt của họ cộng hưởng.","anchor":"đây là đạo tắc cộng hưởng, pháp lực gột rửa a"}]},"nguon":["@c1363"]},{"id":"toi-huyet-vo-van","name":"Tội Huyết vỡ vân","cn":"","aliases":[],"loai":"khac","loaiLabel":"Hiện tượng huyết mạch","phamCap":"Không rõ","hePhai":"Huyết mạch Thạch Tộc","soHuu":["Thạch Hạo","Người Thạch Tộc"],"blurb":"Hiện tượng huyết mạch xuất hiện trên xương trán của hậu duệ Thạch Tộc khi cảm xúc kích động.","detail":"Khi người mang huyết mạch Thạch Tộc kích động hoặc nổi giận, xương trán có thể phát sáng, hiện một chữ cổ và sinh ra sức mạnh chưa rõ bản chất.","thuocTinh":"Huyết mạch","uyLuc":"Có thể sinh ra một sức mạnh không tên khi chữ cổ hiện lên.","dacDiem":"Biểu hiện qua ánh sáng và chữ cổ trên xương trán.","congNang":["Hiện chữ cổ trên xương trán và sinh ra sức mạnh khi cảm xúc kích động."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1364","tangDatToi":"Đã hiện dấu ấn","trangThai":"Đang có"}],"tabs":{"tienTrinh":[{"chuong":"@c1364","loai":"xuất hiện","importance":"normal","giaiDoan":"Dấu ấn huyết mạch","text":"Dấu ấn trên xương trán của Thạch Hạo và người trong bộ lạc cho thấy họ có chung huyết mạch, đồng thời chữ cổ có thể sinh ra sức mạnh khi cảm xúc kích động.","anchor":"sẽ hiện lên một cái chữ cổ, sản sinh không tên sức mạnh"}]},"capNhatToi":"@c1364","nguon":["@c1364"]},{"id":"than-niem-mot-don","name":"Thần niệm một đòn","cn":"","loai":"bi-thuat","loaiLabel":"Phương thức giao đấu thần hồn","phamCap":"","hePhai":"","soHuu":["Thạch Hạo","Kim Chí Phi"],"blurb":"Phương thức giao đấu dùng một lần va chạm thần niệm để nhanh chóng phân định thắng bại.","detail":"Kim Chí Phi đề nghị dùng phương thức này trong cuộc luận bàn với Thạch Hạo trước lúc xuất chinh, khiến cuộc đối đầu chuyển sang va chạm hồn phách nguy hiểm.","congNang":["Phân thắng bại bằng một lần va chạm thần niệm."],"nguoiTu":[{"ten":"Kim Chí Phi","tuChuong":"@c1368","tangDatToi":"","trangThai":"đề nghị thi triển"},{"ten":"Thạch Hạo","tuChuong":"@c1368","tangDatToi":"","trangThai":"chấp nhận giao đấu"}],"tabs":{"tienTrinh":[{"chuong":"@c1368","loai":"xuất hiện","importance":"normal","giaiDoan":"Được chọn làm cách luận bàn","text":"Kim Chí Phi đề nghị hai bên dùng thần niệm một đòn để nhanh chóng phân thắng bại, và Thạch Hạo đồng ý.","anchor":"không bằng ngươi ta từng người động dùng thần niệm một đòn"}]},"capNhatToi":"@c1368","nguon":["@c1368"]},{"id":"ren-luyen-hon-phach-cua-kim-gia","name":"Rèn luyện hồn phách của Kim gia","cn":"","loai":"bi-thuat","loaiLabel":"Pháp môn rèn luyện nguyên thần","phamCap":"","hePhai":"Kim gia","soHuu":["Kim Chí Phi"],"blurb":"Phương pháp do cao thủ Kim gia dùng để rèn luyện hồn phách và củng cố nguyên thần.","detail":"Sau khi Kim Chí Phi ăn nhầm Dưỡng hồn thần thảo khi còn nhỏ, cao thủ trong tộc đã dùng nhiều cách rèn luyện hồn phách cho hắn, khiến nguyên thần trở nên đặc biệt mạnh.","thuocTinh":"Rèn luyện hồn phách","congNang":["Củng cố hồn phách và tăng cường nguyên thần."],"nguoiTu":[{"ten":"Kim Chí Phi","tuChuong":"@c1368","tangDatToi":"Nguyên thần đặc biệt mạnh","trangThai":"đã được rèn luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c1368","loai":"xuất hiện","importance":"normal","giaiDoan":"Nguồn gốc nguyên thần mạnh","text":"Kim Chí Phi được cao thủ Kim gia dùng nhiều phương pháp rèn luyện hồn phách sau khi ăn Dưỡng hồn thần thảo.","anchor":"cũng được trong tộc cao thủ giúp đỡ, mọi cách rèn luyện hồn phách"}]},"capNhatToi":"@c1368","nguon":["@c1368"]},{"id":"truyen-tong-tran-xuat-quan","name":"Truyền Tống trận xuất quan","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Đế quan","soHuu":[],"blurb":"Trận pháp vận chuyển từng đội quân từ khu vực tập kết trong Đế quan tới tế đàn gần giới môn.","detail":"Thạch Hạo và các nhánh quân đội tiến vào trận pháp này trong quá trình xuất quan. Công dụng được thể hiện là truyền tống đại quân tới tuyến tế đàn gần giới môn.","thuocTinh":"Truyền tống","congNang":["Truyền tống đại quân tới tuyến xuất quan @c1369"],"capNhatToi":"@c1369","tabs":{"tienTrinh":[{"chuong":"@c1369","loai":"xuất hiện","importance":"normal","giaiDoan":"Vận chuyển quân đội","text":"Trận pháp đưa Thạch Hạo cùng các đội quân từ khu vực tập kết tới tuyến tế đàn xuất quan.","anchor":"Thạch Hạo cũng tới đường, tiến nhập Truyền Tống trận"}]},"nguon":["@c1369"]},{"id":"te-dan-gioi-mon","name":"Tế đàn giới môn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Đế quan","soHuu":[],"blurb":"Trận pháp tế đàn mở thông lộ xuyên qua giới môn, đưa đại quân từ Đế quan tới chiến trường quan ngoại.","detail":"Các lão giả lắp mảnh xương vàng vào khe trên tế đàn để dựng màn sáng và mở thông lộ. Quá trình vượt qua khiến tu sĩ có cảm giác thân thể bị phân giải và thời gian trở nên hỗn loạn.","thuocTinh":"Không gian","dacDiem":"Thông lộ gây cảm giác thân thể bị phân giải và thời gian hỗn loạn.","congNang":["Mở thông lộ xuyên giới môn để chuyển đại quân ra quan ngoại @c1369"],"capNhatToi":"@c1369","tabs":{"tienTrinh":[{"chuong":"@c1369","loai":"xuất hiện","importance":"normal","giaiDoan":"Mở đường xuất quan","text":"Các lão giả dùng mảnh xương vàng kích hoạt tế đàn, dựng thông lộ xuyên giới môn cho đại quân.","anchor":"đồng thời lấy ra kim sắc mảnh xương, điền tại trên tế đàn trong khe hở"}]},"nguon":["@c1369"]},{"id":"dai-tran-xung-kich-thien-uyen","name":"Đại trận xung kích Thiên Uyên","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Dị vực"],"blurb":"Đại trận quy mô lớn do dị vực dựng trên chiến trường Biên Hoang nhằm phá hoại Thiên Uyên.","detail":"Dị vực huy động nhiều sinh linh và vật liệu để xây dựng trận pháp, dự định xung kích bình chướng Thiên Uyên và mở đường cho Bất Hủ vượt giới. Công trình bị quân Cửu Thiên Thập Địa phát hiện khi chưa hoàn chỉnh.","thuocTinh":"Trận pháp công kích","congNang":["Xung kích và phá hoại Thiên Uyên để chuẩn bị đường vượt giới cho Bất Hủ."],"nguoiTu":[{"ten":"Dị vực","tuChuong":"@c1370","tangDatToi":"Đang bố trí","trangThai":"Chưa hoàn chỉnh"}],"trangThai":"Chưa hoàn chỉnh","capNhatToi":"@c1370","tabs":{"tienTrinh":[{"chuong":"@c1370","loai":"xuất hiện","importance":"normal","giaiDoan":"Đang bố trí","text":"Dị vực dựng đại trận nhằm xung kích và phá hoại Thiên Uyên, nhưng quân Cửu Thiên Thập Địa phát hiện công trình trước khi nó hoàn chỉnh.","anchor":"bọn họ ở bố đại trận, muốn xung kích Thiên Uyên, phá hoại nơi này"}]},"nguon":["@c1370"]},{"id":"chien-tran-quan-doan-cuu-thien","name":"Chiến trận quân đoàn Cửu Thiên","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Cửu Thiên Thập Địa","soHuu":["Cửu Thiên Thập Địa"],"blurb":"Chiến trận được các quân đoàn Cửu Thiên Thập Địa triển khai trước khi xung phong vào đại quân dị vực.","detail":"Quang mang từ đội hình các binh đoàn hợp lại thành một lồng năng lượng, bảo vệ đại quân trong lúc tác chiến.","thuocTinh":"Trận pháp phòng hộ quân đoàn","congNang":["Hợp quang mang của quân trận thành lồng năng lượng bảo vệ đại quân."],"nguoiTu":[{"ten":"Các quân đoàn Cửu Thiên Thập Địa","tuChuong":"@c1370","tangDatToi":"Triển khai trên chiến trường","trangThai":"Đang sử dụng"}],"trangThai":"Đang sử dụng","capNhatToi":"@c1370","tabs":{"tienTrinh":[{"chuong":"@c1370","loai":"thi triển","importance":"normal","giaiDoan":"Triển khai tác chiến","text":"Các quân đoàn triển khai chiến trận, hợp quang mang thành lồng năng lượng phòng hộ trước khi xung phong.","anchor":"hình thành năng lượng lồng ánh sáng, bảo vệ đại quân"}]},"nguon":["@c1370"]},{"id":"to-thuat-than-ho","name":"Tổ thuật thần hồ","cn":"","loai":"than-thong","loaiLabel":"Tổ thuật","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Sinh linh màu bạc"],"blurb":"Tổ thuật dùng Thánh Quang ngưng tụ thành một tòa thần hồ, hấp thu thiên địa tinh hoa để áp chế và tiêu diệt đối thủ.","detail":"Sinh linh màu bạc thi triển tổ thuật này khi đối đầu Thạch Hạo. Thần hồ do Thánh Quang tạo thành không ngăn được quyền lực của Thạch Hạo và bị phá vỡ.","thuocTinh":"Thánh Quang","uyLuc":"Có thể hấp thu thiên địa tinh hoa và áp chế công kích của đối thủ.","dacDiem":"Biểu hiện thành một tòa thần hồ phun nuốt thiên địa tinh hoa.","congNang":["Tạo thần hồ bằng Thánh Quang để hấp thu thiên địa tinh hoa và áp chế đối thủ."],"nguoiTu":[{"ten":"Sinh linh màu bạc","tuChuong":"@c1371","tangDatToi":"Có thể thi triển","trangThai":"Đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c1371","loai":"thi triển","importance":"normal","giaiDoan":"Thi triển trên chiến trường","text":"Sinh linh màu bạc tạo thần hồ bằng Thánh Quang để áp chế quyền của Thạch Hạo nhưng bị phá vỡ.","anchor":"Này sinh linh vận dụng tổ thuật, Thánh Quang bốc hơi, hình thành một toà thần Hồ, phun ra nuốt vào thiên địa tinh hoa, áp chế Thạch Hạo nắm đấm, muốn đem hắn tiêu diệt ở đây."}]},"capNhatToi":"@c1371","nguon":["@c1371"]},{"id":"thien-la-dia-vong","name":"Thiên la địa võng","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Thần thông mạnh nhất của Ngân Chu Vương","hePhai":"Dị vực","soHuu":["Ngân Chu Vương"],"blurb":"Thần thông của Ngân Chu Vương, kết hợp tràng vực, liên y và thần lực dạng tơ thành một tấm lưới bát quái.","detail":"Thiên la địa võng có thể hút và luyện Nguyên Thần, kể cả tác động tới người đứng quan chiến. Thần thông bị lôi kiếp do Thạch Hạo gọi ra thiêu hủy hoàn toàn.","thuocTinh":"Tràng vực và thần lực dạng tơ","uyLuc":"Có thể hút và luyện Nguyên Thần.","dacDiem":"Kết thành lưới bát quái bao phủ mục tiêu.","chieuTieuBieu":"Thiên la địa võng","trangThai":"Bị Bảo thuật Lôi Đế phá hủy trong lần thi triển tại Biên Hoang","capNhatToi":"@c1373","congNang":["Hút và luyện Nguyên Thần của sinh linh nằm trong phạm vi ảnh hưởng."],"nguoiTu":[{"ten":"Ngân Chu Vương","tuChuong":"@c1373","tangDatToi":"Thần thông mạnh nhất","trangThai":"Đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c1373","loai":"thi triển","importance":"normal","giaiDoan":"Đối chiến Thạch Hạo","text":"Ngân Chu Vương thi triển Thiên la địa võng để hút và luyện Nguyên Thần, nhưng toàn bộ mạng nhện bị Bảo thuật Lôi Đế thiêu hủy.","anchor":"Nó không dám có chút bất cẩn, vận dụng tự thân mạnh nhất thần thông"}]},"nguon":["@c1373"]},{"id":"tuyet-the-dai-tran-pha-hoai-thien-uyen","name":"Tuyệt thế đại trận phá hoại Thiên Uyên","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Tuyệt thế đại trận","hePhai":"Dị vực","soHuu":["Dị vực"],"blurb":"Tuyệt thế đại trận phá hoại Thiên Uyên là công trình bày trận quy mô lớn của dị vực, được dùng nhằm phá hoại Thiên Uyên và mở đường cho Bất Hủ giả vượt qua. Đại trận từng khiến Thiên Uyên rung động, nhưng cuối cùng bị bình chướng phản phệ rồi nổ tung.","detail":"Khi được dị vực kích hoạt, đại trận phóng ra huyết quang ngập trời, vô số phù văn cùng bóng mờ vạn linh đồng loạt xung kích Thiên Uyên. Cuộc công kích chỉ khiến Thiên Uyên rung động trong chốc lát rồi bị phản chấn; khu vực bày trận nổ tung, toàn bộ trận kỳ và vật liệu quý bị mất, những người chủ trì cũng bị hút mất. @c1374","thuocTinh":"Trận pháp công kích bình chướng","nguonGoc":"Công trình bày trận của dị vực","uyLuc":"Có thể khiến Thiên Uyên rung động trong chốc lát, nhưng không chống nổi sự phản phệ của bình chướng này và cuối cùng bị phá hủy. @c1374","dacDiem":"Đại trận quy mô lớn của dị vực, lấy huyết quang, phù văn dày đặc và bóng mờ vạn linh làm biểu hiện công kích đặc trưng.","trangThai":"Đã tan rã","capNhatToi":"@c1374","congNang":["Công kích và thử phá hoại Thiên Uyên để mở đường cho Bất Hủ giả vượt qua. @c1374","Triển khai huyết quang, phù văn và bóng mờ vạn linh đồng loạt xung kích Thiên Uyên. @c1374"],"tabs":{"tienTrinh":[{"chuong":"@c1374","loai":"xuất hiện","importance":"major","giaiDoan":"Khởi động rồi tan rã","text":"Dị vực kích hoạt đại trận để công kích Thiên Uyên, nhưng trận pháp bị phản phệ, nổ tung và mất toàn bộ vật liệu trọng yếu.","anchor":"Dị vực ở đây có công trình vĩ đại, là ở bày trận"}]},"nguon":["@c1374"]},{"id":"bat-huu-thien-dao-quyet","name":"Bất Hủ Thiên Đao quyết","cn":"","loai":"kiem-quyet","loaiLabel":"Đao quyết","phamCap":"Bất Hủ giả truyền xuống","hePhai":"Dị vực","soHuu":["Vũ Phong","Khải Dân Bất Hủ"],"blurb":"Đao quyết do Khải Dân Bất Hủ trực tiếp truyền cho Vũ Phong. Pháp môn cần phối hợp một loại tổ thuật thần bí để vận chuyển.","detail":"Khi được Vũ Phong thi triển cùng tổ thuật thần bí, đao quyết cô đọng thế công vào Thiên Đao ấn và tạo ra hàng vạn tầng đao quang trắng bạc.","thuocTinh":"Đao đạo","nguonGoc":"Do Khải Dân Bất Hủ trực tiếp truyền thụ.","yeuCau":"Phải nắm giữ một loại tổ thuật thần bí để vận chuyển.","uyLuc":"Tạo ra đao quang tầng tầng và cường hóa Thiên Đao ấn.","dacDiem":"Khi dung hợp với tổ thuật tương ứng được ca tụng là đại pháp vô địch.","chieuTieuBieu":"Thiên Đao ấn","trangThai":"Đang được Vũ Phong tu luyện","capNhatToi":"@c1376","congNang":["Cường hóa Thiên Đao ấn và sinh ra hàng vạn tầng đao quang trắng bạc."],"nguoiTu":[{"ten":"Vũ Phong","tuChuong":"@c1376","tangDatToi":"Có thể thi triển cùng tổ thuật thần bí","trangThai":"Đang tu luyện"},{"ten":"Khải Dân Bất Hủ","tuChuong":"@c1376","tangDatToi":"Người truyền thụ","trangThai":"Không rõ"}],"tabs":{"tienTrinh":[{"chuong":"@c1376","loai":"thi triển","importance":"normal","giaiDoan":"Vũ Phong giao chiến với Thạch Hạo","text":"Vũ Phong vận chuyển Bất Hủ Thiên Đao quyết cùng tổ thuật thần bí để cô đọng Thiên Đao ấn và đối đầu quyền ấn của Thạch Hạo.","anchor":"Đây chính là một việc cực kỳ đáng sợ đao quyết, nhất định phải nắm giữ một loại thần bí tổ thuật mới có thể vận chuyển"}]},"nguon":["@c1376"]},{"id":"to-thuat-than-bi-phoi-hop-thien-dao-quyet","name":"Tổ thuật thần bí phối hợp Thiên Đao quyết","cn":"","loai":"bi-thuat","loaiLabel":"Tổ thuật","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Vũ Phong"],"blurb":"Một tổ thuật chưa rõ tên được dùng làm điều kiện vận chuyển Bất Hủ Thiên Đao quyết. Khi hai pháp môn dung hợp, Dị vực gọi đó là đại pháp vô địch.","detail":"Tổ thuật được Vũ Phong phối hợp với đao quyết để đẩy uy lực của Thiên Đao ấn tới cực hạn.","thuocTinh":"Tổ thuật","yeuCau":"Phối hợp với Bất Hủ Thiên Đao quyết.","uyLuc":"Gia tăng uy lực của Thiên Đao ấn khi dung hợp với đao quyết.","dacDiem":"Tên riêng và nguồn gốc cụ thể chưa được tiết lộ.","trangThai":"Đang được Vũ Phong sử dụng","capNhatToi":"@c1376","congNang":["Phối hợp Bất Hủ Thiên Đao quyết và tăng cường Thiên Đao ấn."],"nguoiTu":[{"ten":"Vũ Phong","tuChuong":"@c1376","tangDatToi":"Có thể dung hợp với Bất Hủ Thiên Đao quyết","trangThai":"Đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c1376","loai":"thi triển","importance":"normal","giaiDoan":"Dung hợp cùng đao quyết","text":"Vũ Phong dung hợp tổ thuật thần bí với Bất Hủ Thiên Đao quyết để tăng uy lực đòn đánh.","anchor":"hai người dung hợp, được xưng Vô Địch đại pháp, là Bất Hủ giả truyền xuống"}]},"nguon":["@c1376"]},{"id":"thien-dao-an","name":"Thiên Đao ấn","cn":"","loai":"than-thong","loaiLabel":"Đao ấn","phamCap":"Không rõ","hePhai":"Dị vực","soHuu":["Vũ Phong"],"blurb":"Đao ấn được Vũ Phong kết bằng bàn tay phải trắng bạc. Khi chém xuống, nó sinh ra đao mang dài hàng vạn trượng.","detail":"Thiên Đao ấn được Bất Hủ Thiên Đao quyết và tổ thuật thần bí gia trì, nhưng cuối cùng bị ba quyền của Thạch Hạo đánh trúng và phá vỡ thế công.","thuocTinh":"Đao đạo","uyLuc":"Bàn tay hóa thành đao, chém ra đao mang dài hàng vạn trượng.","dacDiem":"Được kết bằng bàn tay phải hóa trắng bạc.","trangThai":"Đang được Vũ Phong sử dụng","capNhatToi":"@c1376","congNang":["Biến bàn tay thành đao ấn và chém ra đao mang quy mô lớn."],"nguoiTu":[{"ten":"Vũ Phong","tuChuong":"@c1376","tangDatToi":"Có thể phối hợp cùng Bất Hủ Thiên Đao quyết","trangThai":"Đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c1376","loai":"thi triển","importance":"normal","giaiDoan":"Đối đầu quyền ấn","text":"Vũ Phong kết Thiên Đao ấn bằng tay phải rồi chém về phía Thạch Hạo, nhưng đao ấn liên tiếp trúng ba quyền.","anchor":"tay phải trắng bạc, tạo thành Thiên Đao ấn, hướng về Thạch Hạo bổ tới"}]},"nguon":["@c1376"]},{"id":"sieu-cap-truyen-tong-tran-di-vuc","name":"Siêu cấp truyền tống trận dị vực","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Siêu cấp","hePhai":"Dị vực","soHuu":["Các tộc dị vực"],"blurb":"Trận pháp truyền tống quy mô lớn được các tộc dị vực sử dụng sau khi thu quân.","detail":"Sau khi rời chiến trường, các tộc dị vực thông qua trận pháp này để nhanh chóng trở về lãnh địa riêng.","thuocTinh":"Không gian và truyền tống","congNang":["Truyền tống đại quân dị vực tới lãnh địa của các tộc."],"nguoiTu":[],"trangThai":"Đang được sử dụng","capNhatToi":"@c1377","tabs":{"tienTrinh":[{"chuong":"@c1377","loai":"xuất hiện","importance":"normal","giaiDoan":"Đưa quân trở về","text":"Các tộc dị vực sử dụng siêu cấp truyền tống trận để trở về lãnh địa sau khi rút khỏi đại mạc.","anchor":"Các tộc trở về sau, đều là thông qua siêu cấp trước truyền tống trận"}]},"dinhDanh":"goc","nguon":["@c1377"]},{"id":"ban-tay-mau-vang-cua-thach-hao","name":"Bàn tay màu vàng của Thạch Hạo","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Thạch Hạo"],"blurb":"Thạch Hạo hóa ra một bàn tay lớn màu vàng để trấn sát kẻ địch.","detail":"Bàn tay lớn như phòng ốc, ép sụp hư không và đồng thời giết hậu bối Kim gia cùng chiến phó trong một đòn.","thuocTinh":"Màu vàng","uyLuc":"Ép sụp hư không và giết hai tu sĩ trong một lần thi triển.","dacDiem":"Bàn tay hóa lớn như một gian phòng.","congNang":["Hóa thành bàn tay lớn màu vàng để trấn áp và giết nhiều mục tiêu cùng lúc."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1381","tangDatToi":"","trangThai":"đang sử dụng"}],"trangThai":"Đang được Thạch Hạo sử dụng","capNhatToi":"@c1381","tabs":{"tienTrinh":[{"chuong":"@c1381","loai":"thi triển","importance":"normal","giaiDoan":"Trấn sát tại thịnh hội","text":"Thạch Hạo hóa ra bàn tay màu vàng lớn như phòng ốc, ép sụp hư không và giết hậu bối Kim gia cùng chiến phó.","anchor":"bàn tay màu vàng óng đại như phòng ốc, ép sụp hư không"}]},"nguon":["@c1381"]},{"id":"ba-loai-bao-thuat-cua-kim-chi-phi","name":"Ba loại bảo thuật của Kim Chí Phi","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Không rõ","hePhai":"Kim gia","soHuu":["Kim Chí Phi"],"blurb":"Ba bảo thuật được Kim Chí Phi đồng thời vận dụng để áp chế Thạch Hạo.","detail":"Ba thủ đoạn lần lượt tạo ra sấm sét từ miệng, Nhai Tí từ bảo quang tay phải và sát kiếm từ dấu ấn đỏ nơi mi tâm. Chúng đều bị biển sét do Bảo thuật Lôi Đế dẫn động áp chế hoặc phá hủy.","thuocTinh":"Lôi đình, diễn hóa sinh linh và sát kiếm","congNang":["Phối hợp sấm sét, Nhai Tí công kích và sát kiếm để cùng lúc tấn công đối thủ."],"nguoiTu":[{"ten":"Kim Chí Phi","tuChuong":"@c1383","tangDatToi":"Có thể đồng thời thi triển ba loại","trangThai":"đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c1383","loai":"thi triển","importance":"normal","giaiDoan":"Đồng thời vận dụng","text":"Kim Chí Phi đồng thời thi triển ba bảo thuật để công kích Thạch Hạo, nhưng chúng lần lượt bị Lôi Đế pháp phá giải.","anchor":"hắn liền vận dụng ba loại bảo thuật, hướng về Thạch Hạo công kích"}]},"capNhatToi":"@c1383","nguon":["@c1383"]},{"id":"tien-dao-phap-an-cua-kim-gia","name":"Tiên Đạo pháp ấn của Kim gia","cn":"","loai":"than-thong","loaiLabel":"Pháp ấn","phamCap":"Truyền thừa Chân Tiên","hePhai":"Kim gia","soHuu":["Kim Chí Phi"],"blurb":"Tuyệt học của Kim gia do một vị Chân Tiên lưu lại.","detail":"Pháp ấn phủ kim quang quanh Kim Chí Phi như giáp trụ, khiến hai tay hắn mang thế trấn áp như tiên sơn và có thể tiếp tục diễn hóa thành Kim Cương Tiên thiên công.","thuocTinh":"Tiên đạo và kim quang","nguonGoc":"Truyền thừa do một vị Chân Tiên của Kim gia lưu lại.","congNang":["Dùng kim quang hộ thể và tạo sức trấn áp lên đối thủ.","Có thể tiếp tục diễn hóa thành Kim Cương Tiên thiên công."],"nguoiTu":[{"ten":"Kim Chí Phi","tuChuong":"@c1383","tangDatToi":"Có thể diễn hóa thành Kim Cương Tiên thiên công","trangThai":"đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c1383","loai":"thi triển","importance":"normal","giaiDoan":"Diễn hóa cổ thiên công","text":"Kim Chí Phi vận chuyển Tiên Đạo pháp ấn của Kim gia để hộ thể, trấn áp đối thủ và diễn hóa Kim Cương Tiên thiên công.","anchor":"Đây là Kim gia tuyệt học, thuộc về Tiên Đạo pháp ấn"}]},"capNhatToi":"@c1383","nguon":["@c1383"]},{"id":"kim-cuong-tien-thien-cong","name":"Kim Cương Tiên thiên công","cn":"","loai":"cong-phap","loaiLabel":"Cổ thiên công","phamCap":"Truyền thừa Chân Tiên","hePhai":"Kim gia","soHuu":["Kim Chí Phi"],"blurb":"Cổ thiên công của Kim gia được diễn hóa từ Tiên Đạo pháp ấn.","detail":"Khi thi triển, thân thể Kim Chí Phi trở nên như vàng ròng và phía sau hiện ra hình bóng Kim Cương Tiên. Môn thiên công va chạm trực diện với Lục Đạo Luân Hồi, phá tan sáu cánh cửa nhưng cũng bị đánh nổ.","thuocTinh":"Kim quang và tiên đạo","nguonGoc":"Kim gia","uyLuc":"Có thể phá tan Lục Đạo Luân Hồi trong một lần đối đầu trực diện.","dacDiem":"Khi vận chuyển sẽ hiện ra hình bóng Kim Cương Tiên và khiến thân thể người thi triển như vàng ròng.","congNang":["Hiện hóa Kim Cương Tiên để trấn áp và xé nát thần thông đối địch."],"nguoiTu":[{"ten":"Kim Chí Phi","tuChuong":"@c1383","tangDatToi":"Đẩy tới cực hạn","trangThai":"đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c1383","loai":"thi triển","importance":"normal","giaiDoan":"Đẩy tới cực hạn","text":"Kim Chí Phi thi triển Kim Cương Tiên thiên công để đối đầu Lục Đạo Luân Hồi rồi tiếp tục đẩy môn công pháp này đến cực hạn.","anchor":"Kim gia cổ thiên công, Kim Cương Tiên thiên công"}]},"capNhatToi":"@c1383","nguon":["@c1383"]},{"id":"chuong-ngu-thien-kiep","name":"Chưởng ngự thiên kiếp","cn":"","loai":"bi-thuat","loaiLabel":"Pháp môn cảm ngộ lôi kiếp","phamCap":"","hePhai":"Lôi đạo","soHuu":["Thạch Hạo"],"blurb":"Hướng cảm ngộ giúp người tu hành điều động sức mạnh thiên kiếp để đối địch.","detail":"Thạch Hạo suy tư con đường để con người chưởng ngự thiên kiếp sau khi điều động Lôi Trì áp chế các trưởng bối Trảm Ngã cảnh.","thuocTinh":"Lôi đình và thiên kiếp","uyLuc":"Có thể ngự Lôi Trì tấn công đối thủ.","dacDiem":"Gắn với việc cảm ngộ và điều động sức mạnh thiên kiếp.","chieuTieuBieu":["Ngự Lôi Trì"],"congNang":["Điều động Lôi Trì để đối địch."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1384","tangDatToi":"Đang suy tư và cảm ngộ","trangThai":"đang tu"}],"trangThai":"Đang được Thạch Hạo cảm ngộ","capNhatToi":"@c1384","tabs":{"tienTrinh":[{"chuong":"@c1384","loai":"xuất hiện","importance":"normal","giaiDoan":"Bước đầu suy tư","text":"Thạch Hạo suy tư con đường để người tu hành chưởng ngự thiên kiếp sau khi vận dụng Lôi Trì.","anchor":"suy tư người vì là chưởng ngự thiên kiếp các loại vấn đề"}]},"nguon":["@c1384"]},{"id":"quan-tuong-loi-tri","name":"Quan tưởng Lôi Trì","cn":"","loai":"bi-thuat","loaiLabel":"Pháp môn ngộ đạo","phamCap":"Chưa rõ","hePhai":"Lôi đạo","soHuu":["Thạch Hạo"],"blurb":"Quan tưởng Lôi Trì là pháp môn do Thạch Hạo tự lĩnh ngộ khi suy ngẫm con đường chưởng ngự Thiên Kiếp của Lôi Đế. Hắn dùng nội tâm cấu trúc, tái hiện Lôi Trì và ngưng tụ thành quả ngộ đạo thành ấn ký trên xương trán.","detail":"Thạch Hạo dựa trên sự suy ngẫm về con đường chưởng ngự Thiên Kiếp của Lôi Đế để tự quan tưởng một Lôi Trì vuông vắn cỡ một tấc trước mi tâm. Khi hình ảnh Lôi Trì nổ tung, điện quang không làm hắn bị thương mà hội tụ, ngưng kết thành ấn ký Lôi Trì trên xương trán. Đây là thành quả từ quá trình hắn dùng nội tâm cấu trúc và tái hiện Lôi Trì. @c1385","thuocTinh":"Lôi đạo","nguonGoc":"Thạch Hạo suy ngẫm con đường chưởng ngự Thiên Kiếp của Lôi Đế rồi tự quan tưởng.","uyLuc":"Có thể tái hiện hình thái Lôi Trì; khi hình ảnh này nổ tung, điện quang hội tụ thành ấn ký trên xương trán mà không làm Thạch Hạo bị thương. @c1385","dacDiem":"Lấy tâm niệm làm phương thức quan tưởng, cấu trúc và tái hiện một Lôi Trì vuông vắn cỡ một tấc trước mi tâm.","chieuTieuBieu":["Tái hiện Lôi Trì","Ngưng tụ ấn ký Lôi Trì"],"congNang":["Dùng nội tâm cấu trúc và tái hiện hình thái Lôi Trì trước mi tâm. @c1385","Ngưng tụ thành quả ngộ đạo thành ấn ký Lôi Trì trên xương trán. @c1385"],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1385","tangDatToi":"Ngộ đạo có thành","trangThai":"dang-tu"}],"trangThai":"Đang được Thạch Hạo lĩnh ngộ","capNhatToi":"@c1385","tabs":{"tienTrinh":[{"chuong":"@c1385","loai":"xuất hiện","importance":"major","giaiDoan":"Ngộ đạo có thành","text":"Thạch Hạo dùng nội tâm cấu trúc và tái hiện Lôi Trì, sau đó ngưng tụ thành ấn ký trên xương trán.","anchor":"Hắn tại ngộ đạo, tại nội tâm quan tưởng, cấu trúc, tái hiện Lôi Trì!"}]},"nguon":["@c1385"]},{"id":"to-thuat-ngan-hoa","name":"Tổ thuật ngân hóa","cn":"","loai":"than-thong","loaiLabel":"Tổ thuật","phamCap":"Không rõ","hePhai":"Vương tộc dị vực","soHuu":["Ngân giáp vương giả"],"blurb":"Tổ thuật phát ra ánh bạc có khả năng kim loại hóa thân thể sinh linh và đoạn tuyệt sinh cơ.","detail":"Ngân giáp vương giả thi triển tổ thuật này trên chiến trường Cửu Thiên. Ánh bạc khiến nhiều sinh linh hóa thành trạng thái như bạch ngân bất động, nhưng bị Thạch Hạo dùng duy nhất động thiên cùng thần quang trong cơ thể thiêu đốt và phá tan.","thuocTinh":"Ánh bạc và kim loại hóa","uyLuc":"Có thể khiến sinh linh bị ngân hóa, thân thể cứng đờ và mất sinh cơ.","dacDiem":"Hiệu quả biểu hiện bằng ánh bạc lan rộng và biến thân thể mục tiêu thành trạng thái như bạch ngân.","chieuTieuBieu":["Ngân hóa thân thể và đoạn tuyệt sinh cơ"],"congNang":["Kim loại hóa thân thể sinh linh và khiến mục tiêu không thể cử động @c1388","Đoạn tuyệt sinh cơ của mục tiêu bị ánh bạc bao phủ @c1388"],"nguoiTu":[{"ten":"Ngân giáp vương giả","tuChuong":"@c1388","tangDatToi":"Có thể thi triển trong giao chiến","trangThai":"tu-vong"}],"trangThai":"Đã xuất hiện","capNhatToi":"@c1388","tabs":{"tienTrinh":[{"chuong":"@c1388","loai":"thi triển","importance":"normal","giaiDoan":"Đối đầu Thạch Hạo","text":"Ngân giáp vương giả dùng ánh bạc ngân hóa các sinh linh và tấn công Thạch Hạo, nhưng tổ thuật bị duy nhất động thiên phá giải.","anchor":"có thể nhìn thấy liên miên sinh linh ngân hóa, trở thành Bạch Ngân, thịt thân vĩnh cố, không thể động"}]},"nguon":["@c1388"]},{"id":"phien-thien-an","name":"Phiên Thiên ấn","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":[],"blurb":"Một pháp ấn từ trên trời giáng xuống, phóng đại cực nhanh và tạo sức trấn áp diện rộng.","detail":"Phiên Thiên ấn có thể đập sập một vùng đại địa và gây áp lực lớn lên chiến trường.","congNang":["Trấn áp từ trên cao và đập nát đại địa trên phạm vi rộng."],"uyLuc":"Khi giáng xuống có thể làm đại địa diện rộng sụp đổ.","dacDiem":"Có hình thái óng ánh như ôn ngọc và phóng đại nhanh khi hạ xuống.","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1389","loai":"thi triển","importance":"normal","giaiDoan":"Xuất hiện trong tầng trời thứ chín","text":"Phiên Thiên ấn từ trên cao giáng xuống, nhanh chóng phóng đại và đập sập đại địa.","anchor":"Một cái Phiên Thiên ấn hạ xuống, óng ánh ôn ngọc"}]},"capNhatToi":"@c1389","nguon":["@c1389"]},{"id":"bach-kim-than-kiem","name":"Bạch kim thần kiếm","cn":"","loai":"than-thong","loaiLabel":"Đòn đánh bằng thần binh","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":[],"blurb":"Một thanh thần kiếm màu bạch kim được dùng để tập kích Thạch Hạo khi hắn vừa khôi phục sức chiến đấu.","detail":"Kiếm quang lạnh như tuyết lao tới đầu Thạch Hạo, buộc hắn phải tránh né trong gang tấc.","congNang":["Tạo kiếm quang lạnh sáng để tập kích đối thủ ở tốc độ cao."],"uyLuc":"Đòn tập kích suýt chém trúng đầu Thạch Hạo.","dacDiem":"Thân kiếm mang màu bạch kim, kiếm quang sáng lạnh như tuyết.","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1389","loai":"thi triển","importance":"normal","giaiDoan":"Tập kích Thạch Hạo","text":"Bạch kim thần kiếm được một sinh linh vung tới, suýt chém trúng đầu Thạch Hạo khi hắn vừa hồi phục.","anchor":"Một đạo sáng như tuyết hàn quang lóng lánh, đó là một thanh bạch kim thần kiếm"}]},"capNhatToi":"@c1389","nguon":["@c1389"]},{"id":"an-lan-chi-mau","name":"An Lan chi mâu","cn":"","loai":"than-thong","loaiLabel":"Thần thông huyết mạch","phamCap":"Không rõ","hePhai":"Đế tộc Dị Vực","soHuu":["Nữ hậu duệ An Lan chưa rõ tên"],"blurb":"Thần năng huyết mạch của hậu duệ An Lan, biểu hiện qua ma văn hình hoàng kim trường thương trên cánh tay.","detail":"Ma văn trường thương hội tụ ánh sáng vào ngón tay rồi phóng ra thần mang hoàng kim mang uy lực của trường thương, đủ sức phá hủy Càn Khôn. Khi đối đầu Luân Hồi quyền, hình thái hoàng kim thương bị sức mạnh thời gian ăn mòn nhưng có thể rũ bỏ lớp rỉ sét và tiếp tục tấn công.","thuocTinh":"Thần năng huyết mạch","nguonGoc":"Huyết mạch hậu duệ An Lan","uyLuc":"Thần mang mang uy lực An Lan chi mâu có thể phá hủy Càn Khôn.","dacDiem":"Được kích hoạt từ ma văn hình trường thương trên cánh tay.","chieuTieuBieu":["Thần mang hoàng kim"],"trangThai":"Đang được nữ hậu duệ An Lan sử dụng","congNang":["Hội tụ thần mang hoàng kim mang uy lực trường thương để công kích mục tiêu."],"nguoiTu":[{"ten":"Nữ hậu duệ An Lan chưa rõ tên","tuChuong":"@c1390","tangDatToi":"Có thể thi triển thần mang hoàng kim","trangThai":"đang-tu"}],"tabs":{"tienTrinh":[{"chuong":"@c1390","loai":"thi triển","importance":"normal","giaiDoan":"Thần năng huyết mạch được vận dụng","text":"Nữ hậu duệ An Lan kích hoạt ma văn trường thương trên cánh tay, ngưng tụ thần mang hoàng kim để tấn công Thạch Hạo và đối đầu Luân Hồi quyền.","anchor":"này chỉ tay lực lượng ẩn chứa An Lan chi mâu thần uy"}]},"capNhatToi":"@c1390","nguon":["@c1390"]},{"id":"an-lan-diet-the-quyet","name":"An Lan Diệt Thế Quyết","cn":"","loai":"than-thong","loaiLabel":"Vô thượng tổ thuật","phamCap":"Vô thượng tổ thuật","hePhai":"An Lan nhất tộc","soHuu":["Nữ hậu nhân An Lan"],"blurb":"Tổ thuật của An Lan nhất tộc được nữ hậu nhân An Lan thi triển sau khi Hoàng Kim trường thương bị phá hủy.","detail":"Chiêu thức được dùng để tiếp tục tấn công Thạch Hạo, nhưng công năng riêng chưa được giải thích.","nguonGoc":"An Lan nhất tộc","nguoiTu":[{"ten":"Nữ hậu nhân An Lan","tuChuong":"@c1391","tangDatToi":"Đã thi triển","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1391","loai":"thi triển","importance":"normal","giaiDoan":"Hiện thế trong Thiên Kiếp","text":"Nữ hậu nhân An Lan thi triển An Lan Diệt Thế Quyết để tấn công Thạch Hạo sau khi trường thương bị phá hủy.","anchor":"“An Lan Diệt Thế Quyết!” Nhưng mà, nàng kia cũng không kinh sợ, trong miệng khẽ quát, thi triển ra khác một bản vô thượng tổ thuật, hướng Thạch Hạo công đi."}]},"capNhatToi":"@c1391","nguon":["@c1391"]},{"id":"lay-than-la-chung","name":"Lấy thân là chủng","cn":"","loai":"cong-phap","loaiLabel":"Con đường tu luyện","phamCap":"Không rõ","hePhai":"Con đường tự thân","soHuu":["Thạch Hạo"],"blurb":"Con đường tu luyện lấy chính thân thể làm nền tảng để thăm dò các bí mật và kho tàng trong huyết nhục.","detail":"Nhờ nhiều năm lấy thân làm chủng, Thạch Hạo nhìn thấy những cánh cửa phân bố trong cơ thể và nhận ra chúng tập trung đặc biệt nhiều ở vùng bụng.","thuocTinh":"Khai phá thân thể","nguonGoc":"Do Thạch Hạo thực hành và thăm dò bí mật trong cơ thể.","congNang":["Giúp người tu nhìn thấy những cánh cửa dẫn tới kho tàng huyết nhục trong cơ thể."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1392","tangDatToi":"Đã nhìn thấy các cửa kho tàng thân thể","trangThai":"đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c1392","loai":"hé lộ tầng-chiêu","importance":"normal","giaiDoan":"Thăm dò kho tàng thân thể","text":"Quá trình lấy thân làm chủng giúp Thạch Hạo nhìn thấy nhiều cánh cửa trong huyết nhục, đặc biệt tập trung ở vùng bụng.","anchor":"Mấy năm qua, hắn lấy thân là chủng, vẫn ở thăm dò trong cơ thể bí mật"}]},"capNhatToi":"@c1392","nguon":["@c1392"]},{"id":"tien-co-kinh-van","name":"Tiên cổ kinh văn","cn":"","loai":"cong-phap","loaiLabel":"Kinh văn","phamCap":"Không rõ","hePhai":"Tiên cổ pháp","soHuu":["Thạch Hạo"],"blurb":"Kinh văn thuộc hệ Tiên cổ được Thạch Hạo triển khai qua ba đạo tiên khí trong phép thử mở đường.","detail":"Kinh văn bao phủ vùng bụng và bảo vệ các cánh cửa nằm quanh khu vực mà duy nhất động thiên sắp bạo phát.","congNang":["Bao phủ vùng bụng và bảo vệ những cánh cửa kho tàng thân thể quanh điểm bạo phát."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1392","tangDatToi":"Có thể triển khai qua ba đạo tiên khí","trangThai":"đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c1392","loai":"thi triển","importance":"normal","giaiDoan":"Bảo vệ cửa kho tàng","text":"Thạch Hạo triển khai Tiên cổ kinh văn qua ba đạo tiên khí để bao phủ bụng và bảo vệ những cánh cửa quanh cực điểm sắp bạo phát.","anchor":"triển khai Tiên cổ kinh văn, bao dung bụng, bảo vệ ở bụng hết thảy môn phụ cận"}]},"capNhatToi":"@c1392","nguon":["@c1392"]},{"id":"luan-hai","name":"Luân Hải","cn":"","loai":"cong-phap","loaiLabel":"Bước tu luyện","phamCap":"Bước thứ nhất","hePhai":"Con đường tu luyện riêng của Thạch Hạo","soHuu":["Thạch Hạo"],"blurb":"Luân Hải là bước đầu tiên trên con đường tu luyện riêng do Thạch Hạo tự phỏng đoán và khai sáng. Bước này bắt đầu bằng việc làm nổ cực điểm trong bụng nhằm mở những cánh cửa dẫn tới kho tàng huyết nhục.","detail":"Thạch Hạo tự định danh Luân Hải khi khai mở con đường tu luyện riêng của mình. Phương hướng của bước này là đưa cực điểm vào vùng bụng rồi làm nó bạo phát, qua đó hướng tới việc mở những cánh cửa dẫn vào kho tàng huyết nhục; tại mốc được ghi nhận, kết quả khai mở vẫn chưa được xác nhận. @c1392","nguonGoc":"Do Thạch Hạo tự phỏng đoán và khai sáng.","yeuCau":"Dung hợp nhiều hệ thống tu luyện và bảo vệ các cánh cửa trong bụng trước khi làm nổ cực điểm.","congNang":["Mở những cánh cửa dẫn tới kho tàng huyết nhục ở vùng bụng."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1392","tangDatToi":"Bắt đầu khai mở bước thứ nhất","trangThai":"đang thử nghiệm"}],"trangThai":"Đang khai mở, chưa xác nhận kết quả","tabs":{"tienTrinh":[{"chuong":"@c1392","loai":"xuất hiện","importance":"major","giaiDoan":"Bước thứ nhất","text":"Thạch Hạo đặt tên Luân Hải cho bước đầu tiên của con đường tu luyện riêng, lấy việc làm nổ cực điểm trong bụng để mở các cửa kho tàng huyết nhục làm khởi đầu.","anchor":"Bước thứ nhất, ta xưng nó vì là —— Luân Hải!"}]},"capNhatToi":"@c1392","nguon":["@c1392"],"dacDiem":"Lấy việc làm nổ cực điểm trong bụng làm khởi đầu cho bước tu luyện đầu tiên. @c1392"},{"id":"doi-phien-hai","name":"Đổi phiên hải","cn":"","loai":"cong-phap","loaiLabel":"Con đường tu luyện trong cơ thể","phamCap":"Sơ thành","hePhai":"Hệ thống do Thạch Hạo tự khai sáng","soHuu":["Thạch Hạo"],"blurb":"Đổi phiên hải là nền móng đầu tiên trên con đường tu luyện do Thạch Hạo tự khai mở từ những cánh cửa trong cơ thể. Công pháp được hình thành khi các cánh cửa tại vùng bụng liên kết, khiến sinh cơ và tử khí giao hòa, đồng thời tập trung lực lượng từ các cửa toàn thân.","detail":"Thạch Hạo khai mở Đổi phiên hải bằng cách liên kết những cánh cửa tại vùng bụng, khiến sinh cơ và tử khí giao hòa và đặt nền móng cho con đường tu luyện của bản thân @c1393. Các cánh cửa trong cơ thể liên kết, tổ hợp và phân hóa thành một khu vực vận chuyển tuần hoàn như Thái Cực; Đổi phiên hải nối với toàn thân để thu nhận và tập trung lực lượng từ những cửa khác.","thuocTinh":"Sinh tử tương y","nguonGoc":"Do Thạch Hạo khai mở từ những cánh cửa trong cơ thể","yeuCau":"Mở những cánh cửa tập trung tại vùng bụng","uyLuc":"Có thể thu nhận và tập trung lực lượng từ các cửa trên toàn thân.","dacDiem":"Sinh cơ và tử khí giao hòa, chuyển hóa tuần hoàn và duy trì trạng thái cân bằng như Thái Cực.","trangThai":"Sơ thành","capNhatToi":"@c1393","congNang":["Thu nhận và tập trung thần lực từ những cánh cửa trên toàn thân.","Duy trì sự chuyển hóa tuần hoàn giữa sinh cơ và tử khí."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1393","tangDatToi":"Mới mở","trangThai":"Đang hoàn thiện"}],"tabs":{"tienTrinh":[{"chuong":"@c1393","loai":"xuất hiện","importance":"major","giaiDoan":"Sơ thành","text":"Thạch Hạo liên kết những cánh cửa tại vùng bụng, khiến sinh cơ và tử khí giao hòa thành đổi phiên hải, đặt nền móng cho con đường tu luyện mới.","anchor":"hải vì tử khí biến thành, đổi phiên mà sống mệnh chi thần mâm, với nhau giao dung"}]},"nguon":["@c1393"]},{"id":"am-duong-than-do-hop-nhat-tam-phap","name":"Âm dương thần đồ hợp nhất tam pháp","cn":"","loai":"than-thong","loaiLabel":"Pháp môn hộ thân và trấn áp","phamCap":"","hePhai":"Hợp nhất Côn Bằng pháp, Liễu Thần pháp và Lôi Đế pháp","soHuu":["Thạch Hạo"],"blurb":"Âm dương thần đồ hợp nhất tam pháp là thần đồ do Thạch Hạo dung hợp Côn Bằng pháp, Liễu Thần pháp và Lôi Đế pháp. Công pháp được dùng để bảo vệ thân thể khi khai mở những cánh cửa trong cơ thể, trấn áp lực phá hoại và điều hòa khí cơ hỗn loạn.","detail":"Thạch Hạo hợp nhất Côn Bằng pháp, Liễu Thần pháp và Lôi Đế pháp thành một thần đồ âm dương, cho thần đồ dung hợp với vùng bụng và phối hợp cùng cốt văn. Trong quá trình khai mở đổi phiên hải, thần đồ có vai trò trấn áp lực bạo phát đang phá hủy thân thể, điều hòa khí cơ hỗn loạn tại vùng bụng và hạn chế thương tổn do những cánh cửa mới mở gây ra. @c1393","thuocTinh":"Âm dương","nguonGoc":"Hợp nhất Côn Bằng pháp, Liễu Thần pháp và Lôi Đế pháp","uyLuc":"Có thể trấn áp lực bạo phát khi mở cửa đang phá hủy thân thể Thạch Hạo. @c1393","dacDiem":"Dung hợp Côn Bằng pháp, Liễu Thần pháp và Lôi Đế pháp thành một thần đồ âm dương.","trangThai":"Đã thi triển","capNhatToi":"@c1393","congNang":["Trấn áp lực bạo phát, phá hoại thân thể khi Thạch Hạo mở những cánh cửa trong cơ thể. @c1393","Điều hòa khí cơ hỗn loạn tại vùng bụng."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1393","tangDatToi":"Đã thi triển","trangThai":"Đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1393","loai":"thi triển","importance":"major","giaiDoan":"Hợp nhất tam pháp","text":"Thạch Hạo hợp nhất Côn Bằng pháp, Liễu Thần pháp và Lôi Đế pháp thành âm dương thần đồ để trấn áp lực phá hoại trong quá trình mở cửa.","anchor":"lấy côn bằng pháp 、 liễu thần pháp 、 lôi đế pháp hợp nhất, tạo thành một âm dương thần đồ"}]},"nguon":["@c1393"]},{"id":"lieu-than-sinh-menh-dai-phap","name":"Liễu Thần sinh mệnh đại pháp","cn":"","loai":"bi-thuat","loaiLabel":"Sinh mệnh đại pháp","phamCap":"Không rõ","hePhai":"Liễu Thần","soHuu":["Thạch Hạo"],"blurb":"Sinh mệnh đại pháp được Thạch Hạo vận dụng như một trong các biện pháp tìm đường sống trước khi lên Trảm Tiên đài.","detail":"Pháp này thuộc những thủ đoạn bảo mệnh Thạch Hạo đã chuẩn bị, nhưng không thể tự giúp hắn chống lại sức chém đồng thời hủy diệt thân thể và nguyên thần của Trảm Tiên đài.","thuocTinh":"Sinh mệnh","congNang":["Giúp người tu tìm đường sống trong tình thế nguy hiểm."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1395","tangDatToi":"Đã vận dụng","trangThai":"đang tu"}],"capNhatToi":"@c1395","tabs":{"tienTrinh":[{"chuong":"@c1395","loai":"thi triển","importance":"normal","giaiDoan":"Biện pháp bảo mệnh","text":"Thạch Hạo vận dụng Liễu Thần sinh mệnh đại pháp cùng nhiều thủ đoạn khác để tìm đường sống trước khi lên Trảm Tiên đài.","anchor":"Lần này, hắn vì sống sót, vận dụng các loại biện pháp, từ Liễu Thần sinh mệnh đại pháp"}]},"nguon":["@c1395"]},{"id":"tien-thien-chan-cuong-cua-kim-trien","name":"Tiên Thiên chân cương của Kim Triển","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Kim Triển","soHuu":["Kim Triển"],"blurb":"Một loại chân cương của Kim Triển có thể giao hòa với hỗn độn.","detail":"Khi được luyện đến cực hạn, Tiên Thiên chân cương được mô tả có khả năng đánh rơi nhật nguyệt, chém phá tinh vực và vũ trụ.","thuocTinh":"Chân cương giao hòa với hỗn độn","uyLuc":"Khi đạt cực hạn có thể đánh rơi nhật nguyệt, chém phá tinh vực và vũ trụ.","nguoiTu":[{"ten":"Kim Triển","tuChuong":"@c1399","tangDatToi":"Không rõ","trangThai":"Đang tu luyện"}],"congNang":["Tạo chân cương giao hòa với hỗn độn để công kích."],"trangThai":"Đang lưu truyền","capNhatToi":"@c1399","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1399","loai":"xuất hiện","importance":"normal","giaiDoan":"Uy lực được mô tả","text":"Tiên Thiên chân cương của Kim Triển được xác nhận có thể giao hòa với hỗn độn và sở hữu uy lực rất lớn khi luyện tới cực hạn.","anchor":"Một cái Tiên Thiên chân cương cùng hỗn độn giao hòa, được xưng có thể đánh xuống nhật nguyệt"}]},"nguon":["@c1399"]}]};
